 moveonly(const moveonly&) = delete;
 moveonly(moveonly&&) = default;
 moveonly& operator=(const moveonly&) = delete;
 moveonly& operator=(moveonly&&) = default;
 ~moveonly() = default;
};
moveonly* p;
moveonly q(*p); // error: deleted copy constructor

— end example]

A deleted function is implicitly an inline function ([dcl.inline]). [Note 2: The one-definition rule ([basic.def.odr]) applies to deleted definitions. — end note] A deleted definition of a function shall be the first declaration of the function or, for an explicit specialization of a function template, the first declaration of that specialization. An implicitly declared allocation or deallocation function ([basic.stc.dynamic]) shall not be defined as deleted. [Example 4:

struct sometype {
 sometype();
};
sometype::sometype() = delete; // error: not first declaration

— end example]

[Example 1:

task<int> f();
task<void> g1() {
 int i = co_await f();
 std::cout << "f() => " << i << std::endl;
}
template <typename... Args>
task<void> g2(Args&&...) { // OK, ellipsis is a pack expansion
 int i = co_await f();
 std::cout << "f() => " << i << std::endl;
}
task<void> g3(int a, ...) { // error: variable parameter list not allowed
 int i = co_await f();
 std::cout << "f() => " << i << std::endl;
}

— end example]

If a search for the name get_return_object_on_allocation_failure in the scope of the promise type ([class.member.lookup]) finds any declarations, then the result of a call to an allocation function used to obtain storage for the coroutine state is assumed to return nullptr if it fails to obtain storage, and if a global allocation function is selected, the:: operator new(size_t, nothrow_t) form is used. The allocation function used in this case shall have a non-throwing noexcept-specifier. If the allocation function returns nullptr, the coroutine returns control to the caller of the coroutine and the return value is obtained by a call to T:: get_return_object_on_allocation_failure(), where T is the promise type.[Example 2:

#include <iostream>
#include <coroutine>
// ​::​operator new(size_t, nothrow_t) will be used if allocation is needed
struct generator {
 struct promise_type;
 using handle = std::coroutine_handle<promise_type>;
 struct promise_type {
 int current_value;
 static auto get_return_object_on_allocation_failure() { return generator{nullptr}; }
 auto get_return_object() { return generator{handle::from_promise(*this)}; }
 auto initial_suspend() { return std::suspend_always{}; }
 auto final_suspend() noexcept { return std::suspend_always{}; }
 void unhandled_exception() { std::terminate(); }
 void return_void() {}
 auto yield_value(int value) {
 current_value = value;
 return std::suspend_always{};
 }
 };
 bool move_next() { return coro ? (coro.resume(), !coro.done()) : false; }
 int current_value() { return coro.promise().current_value; }
 generator(generator const&) = delete;
 generator(generator && rhs) : coro(rhs.coro) { rhs.coro = nullptr; }
 ~generator() { if (coro) coro.destroy(); }
private:
 generator(handle h) : coro(h) {}
 handle coro;
};
generator f() { co_yield 1; co_yield 2; }
int main() {
 auto g = f();
 while (g.move_next()) std::cout << g.current_value() << std::endl;
}

— end example]

Otherwise, all of E's non-static data members shall be direct members of E or of the same base class of E, well-formed when named as e.name in the context of the structured binding, E shall not have an anonymous union member, and the number of elements in the identifier-list shall be equal to the number of non-static data members of E. Designating the non-static data members of E as m0, m1, m2,… (in declaration order), each vi is the name of an lvalue that refers to the member mi of e and whose type is that of e.mi ([expr.ref]); the referenced type is the declared type of mi if that type is a reference type, or the type of e.mi otherwise. The lvalue is a bit-field if that member is a bit-field. [Example 2:

struct S { mutable int x1 : 2; volatile double y1; };
S f();
const auto [ x, y ] = f();

The type of the id-expression x is “int”, the type of the id-expression y is “const volatile double”. — end example]

An enumeration is a distinct type ([basic.compound]) with named constants. Its name becomes an enum-name within its scope. enum-name:identifier enum-specifier:enum-head { enumerator-listopt }enum-head { enumerator-list, } enum-head:enum-key attribute-specifier-seqopt enum-head-nameopt enum-baseopt enum-head-name:nested-name-specifieropt identifier opaque-enum-declaration:enum-key attribute-specifier-seqopt enum-head-name enum-baseopt; enum-key:enumenum classenum struct enum-base:: type-specifier-seq enumerator-list:enumerator-definitionenumerator-list, enumerator-definition enumerator-definition:enumeratorenumerator = constant-expression enumerator:identifier attribute-specifier-seqopt The optional attribute-specifier-seq in the enum-head and the opaque-enum-declaration appertains to the enumeration; the attributes in that attribute-specifier-seq are thereafter considered attributes of the enumeration whenever it is named. A: following “enum nested-name-specifieropt identifier” within the decl-specifier-seq of a member-declaration is parsed as part of an enum-base. [Note 1: This resolves a potential ambiguity between the declaration of an enumeration with an enum-base and the declaration of an unnamed bit-field of enumeration type. [Example 1:

struct S {
 enum E : int {};
 enum E : int {}; // error: redeclaration of enumeration
};

— end example] — end note] The identifier in an enum-head-name is not looked up and is introduced by the enum-specifier or opaque-enum-declaration. If the enum-head-name of an opaque-enum-declaration contains a nested-name-specifier, the declaration shall be an explicit specialization.

The enumeration type declared with an enum-key of only enum is an unscoped enumeration, and its enumerators are unscoped enumerators. The enum-keys enum class and enum struct are semantically equivalent; an enumeration type declared with one of these is a scoped enumeration, and its enumerators are scoped enumerators. The optional enum-head-name shall not be omitted in the declaration of a scoped enumeration. The type-specifier-seq of an enum-base shall name an integral type; any cv-qualification is ignored. An opaque-enum-declaration declaring an unscoped enumeration shall not omit the enum-base. The identifiers in an enumerator-list are declared as constants, and can appear wherever constants are required. The same identifier shall not appear as the name of multiple enumerators in an enumerator-list. An enumerator-definition with = gives the associated enumerator the value indicated by the constant-expression. If the first enumerator has no initializer, the value of the corresponding constant is zero. An enumerator-definition without an initializer gives the enumerator the value obtained by increasing the value of the previous enumerator by one. [Example 2:

enum { a, b, c=0 };
enum { d, e, f=e+2 };

defines a, c, and d to be zero, b and e to be 1, and f to be 3. — end example] The optional attribute-specifier-seq in an enumerator appertains to that enumerator.

The value of an enumerator or an object of an unscoped enumeration type is converted to an integer by integral promotion. [Example 3:

enum color { red, yellow, green=20, blue };
color col = red;
color* cp = &col;
if (*cp == blue) // ...

makes color a type describing various colors, and then declares col as an object of that type, and cp as a pointer to an object of that type. The possible values of an object of type color are red, yellow, green, blue; these values can be converted to the integral values 0, 1, 20, and 21. Since enumerations are distinct types, objects of type color can be assigned only values of type color.

color c = 1; // error: type mismatch, no conversion from int to color
int i = yellow; // OK, yellow converted to integral value 1, integral promotion

Note that this implicit enum to int conversion is not provided for a scoped enumeration:

enum class Col { red, yellow, green };
int x = Col::red; // error: no Col to int conversion
Col y = Col::red;
if (y) { } // error: no Col to bool conversion

— end example]

The name of each unscoped enumerator is also bound in the scope that immediately contains the enum-specifier. An unnamed enumeration that does not have a typedef name for linkage purposes ([dcl.typedef]) and that has a first enumerator is denoted, for linkage purposes ([basic.link]), by its underlying type and its first enumerator; such an enumeration is said to have an enumerator as a name for linkage purposes. [Note 3: Each unnamed enumeration with no enumerators is a distinct type. — end note] [Example 4:

enum direction { left='l', right='r' };
void g() {
 direction d; // OK
 d = left; // OK
 d = direction::right; // OK
}
enum class altitude { high='h', low='l' };
void h() {
 altitude a; // OK
 a = high; // error: high not in scope
 a = altitude::low; // OK
}

— end example]

[Note 1: A using-enum-declaration in class scope makes the enumerators of the named enumeration available via member lookup. [Example 1:

enum class fruit { orange, apple };
struct S {
 using enum fruit; // OK, introduces orange and apple into S
};
void f() {
 S s;
 s.orange; // OK, names fruit​::​orange
 S::orange; // OK, names fruit​::​orange
}

— end example] — end note]

[Note 2: Two using-enum-declarations that introduce two enumerators of the same name conflict. [Example 2:

enum class fruit { orange, apple };
enum class color { red, orange };
void f() {
 using enum fruit; // OK
 using enum color; // error: color​::​orange and fruit​::​orange conflict
}

— end example] — end note]

Because a namespace-definition contains declarations in its namespace-body and a namespace-definition is itself a declaration, it follows that namespace-definitions can be nested. [Example 1:

namespace Outer {
 int i;
 namespace Inner {
 void f() { i++; } // Outer​::​i
 int i;
 void g() { i++; } // Inner​::​i
 }
}

— end example]

A nested-namespace-definition with an enclosing-namespace-specifier E, identifier I and namespace-body B is equivalent to

namespace E { inlineopt namespace I { B } }

where the optional inline is present if and only if the identifier I is preceded by inline. [Example 2:

namespace A::inline B::C {
 int i;
}

The above has the same effect as:

namespace A {
 inline namespace B {
 namespace C {
 int i;
 }
 }
}

— end example]

An unnamed-namespace-definition behaves as if it were replaced by inlineopt namespace unique { /* empty body */ }using namespace unique;namespace unique { namespace-body } where inline appears if and only if it appears in the unnamed-namespace-definition and all occurrences of unique in a translation unit are replaced by the same identifier, and this identifier differs from all other identifiers in the translation unit. The optional attribute-specifier-seq in the unnamed-namespace-definition appertains to unique. [Example 1:

namespace { int i; } // unique​::​i
void f() { i++; } // unique​::​i++
namespace A {
 namespace {
 int i; // A​::​unique​::​i
 int j; // A​::​unique​::​j
 }
 void g() { i++; } // A​::​unique​::​i++
}
using namespace A;
void h() {
 i++; // error: unique​::​i or A​::​unique​::​i
 A::i++; // A​::​unique​::​i
 j++; // A​::​unique​::​j
}

— end example]

[Note 3: A using-directive does not introduce any names. — end note] [Example 1:

namespace A {
 int i;
 namespace B {
 namespace C {
 int i;
 }
 using namespace A::B::C;
 void f1() {
 i = 5; // OK, C​::​i visible in B and hides A​::​i
 }
 }
 namespace D {
 using namespace B;
 using namespace C;
 void f2() {
 i = 5; // ambiguous, B​::​C​::​i or A​::​i?
 }
 }
 void f3() {
 i = 5; // uses A​::​i
 }
}
void f4() {
 i = 5; // error: neither i is visible
}

— end example]

[Note 4: A using-directive is transitive: if a scope contains a using-directive that nominates a namespace that itself contains using-directives, the namespaces nominated by those using-directives are also eligible to be considered. — end note] [Example 2:

namespace M {
 int i;
}
namespace N {
 int i;
 using namespace M;
}
void f() {
 using namespace N;
 i = 7; // error: both M​::​i and N​::​i are visible
}

For another example,

namespace A {
 int i;
}
namespace B {
 int i;
 int j;
 namespace C {
 namespace D {
 using namespace A;
 int j;
 int k;
 int a = i; // B​::​i hides A​::​i
 }
 using namespace D;
 int k = 89; // no problem yet
 int l = k; // ambiguous: C​::​k or D​::​k
 int m = i; // B​::​i hides A​::​i
 int n = j; // D​::​j hides B​::​j
 }
}

— end example]

[Note 6: If name lookup finds a declaration for a name in two different namespaces, and the declarations do not declare the same entity and do not declare functions or function templates, the use of the name is ill-formed ([basic.lookup]). In particular, the name of a variable, function or enumerator does not hide the name of a class or enumeration declared in a different namespace. For example,

namespace A {
 class X { };
 extern "C" int g();
 extern "C++" int h();
}
namespace B {
 void X(int);
 extern "C" int g();
 extern "C++" int h(int);
}
using namespace A;
using namespace B;
void f() {
 X(1); // error: name X found in two namespaces
 g(); // OK, name g refers to the same entity
 h(); // OK, overload resolution selects A​::​h
}

— end note]

[Note 7: The order in which namespaces are considered and the relationships among the namespaces implied by the using-directives do not affect overload resolution. Neither is any function excluded because another has the same signature, even if one is in a namespace reachable through using-directives in the namespace of the other. — end note] [Example 3:

namespace D {
 int d1;
 void f(char);
}
using namespace D;
int d1; // OK, no conflict with D​::​d1
namespace E {
 int e;
 void f(int);
}
namespace D { // namespace extension
 int d2;
 using namespace E;
 void f(int);
}
void f() {
 d1++; // error: ambiguous ​::​d1 or D​::​d1?
 ::d1++; // OK
 D::d1++; // OK
 d2++; // OK, D​::​d2
 e++; // OK, E​::​e
 f(1); // error: ambiguous: D​::​f(int) or E​::​f(int)?
 f('a'); // OK, D​::​f(char)
}

— end example]

In a using-declaration used as a member-declaration, each using-declarator shall either name an enumerator or have a nested-name-specifier naming a base class of the current class ([expr.prim.this]). [Example 1:

enum class button { up, down };
struct S {
 using button::up;
 button b = up; // OK
};

— end example] If a using-declarator names a constructor, its nested-name-specifier shall name a direct base class of the current class. If the immediate (class) scope is associated with a class template, it shall derive from the specified base class or have at least one dependent base class. [Example 2:

struct B {
 void f(char);
 enum E { e };
 union { int x; };
};
struct C {
 int f();
};
struct D : B {
 using B::f; // OK, B is a base of D
 using B::e; // OK, e is an enumerator of base B
 using B::x; // OK, x is a union member of base B
 using C::f; // error: C isn't a base of D
 void f(int) { f('c'); } // calls B​::​f(char)
 void g(int) { g('c'); } // recursively calls D​::​g(int)
};
template <typename... bases>
struct X : bases... {
 using bases::f...;
};
X<B, C> x; // OK, B​::​f and C​::​f named

— end example]

A using-declaration shall not name a template-id. [Example 3:

struct A {
 template <class T> void f(T);
 template <class T> struct X { };
};
struct B : A {
 using A::f<double>; // error
 using A::X<int>; // error
};

— end example]

A using-declaration that names a class member other than an enumerator shall be a member-declaration. [Example 4:

struct X {
 int i;
 static int s;
};
void f() {
 using X::i; // error: X​::​i is a class member and this is not a member declaration.
 using X::s; // error: X​::​s is a class member and this is not a member declaration.
}

— end example]

[Note 3: A using-declarator whose nested-name-specifier names a namespace does not name declarations added to the namespace after it. Thus, additional overloads added after the using-declaration are ignored, but default function arguments ([dcl.fct.default]), default template arguments ([temp.param]), and template specializations ([temp.spec.partial], [temp.expl.spec]) are considered. — end note] [Example 5:

namespace A {
 void f(int);
}
using A::f; // f is a synonym for A​::​f; that is, for A​::​f(int).
namespace A {
 void f(char);
}
void foo() {
 f('a'); // calls f(int), even though f(char) exists.
}
void bar() {
 using A::f; // f is a synonym for A​::​f; that is, for A​::​f(int) and A​::​f(char).
 f('a'); // calls f(char)
}

— end example]

If a declaration named by a using-declaration that inhabits the target scope of another declaration potentially conflicts with it ([basic.scope.scope]), and either is reachable from the other, the program is ill-formed. If two declarations named by using-declarations that inhabit the same scope potentially conflict, either is reachable from the other, and they do not both declare functions or function templates, the program is ill-formed. [Note 4: Overload resolution possibly cannot distinguish between conflicting function declarations. — end note] [Example 6:

namespace A {
 int x;
 int f(int);
 int g;
 void h();
}
namespace B {
 int i;
 struct g { };
 struct x { };
 void f(int);
 void f(double);
 void g(char); // OK, hides struct g
}
void func() {
 int i;
 using B::i; // error: conflicts
 void f(char);
 using B::f; // OK, each f is a function
 using A::f; // OK, but interferes with B​::​f(int)
 f(1); // error: ambiguous
 static_cast<int(*)(int)>(f)(1); // OK, calls A​::​f
 f(3.5); // calls B​::​f(double)
 using B::g;
 g('a'); // calls B​::​g(char)
 struct g g1; // g1 has class type B​::​g
 using A::g; // error: conflicts with B​::​g
 void h();
 using A::h; // error: conflicts
 using B::x;
 using A::x; // OK, hides struct B​::​x
 x = 99; // assigns to A​::​x
 struct x x1; // x1 has class type B​::​x
}

— end example]

The set of declarations named by a using-declarator that inhabits a class C does not include member functions and member function templates of a base class that correspond to (and thus would conflict with) a declaration of a function or function template in C. [Example 7:

struct B {
 virtual void f(int);
 virtual void f(char);
 void g(int);
 void h(int);
};
struct D : B {
 using B::f;
 void f(int); // OK, D​::​f(int) overrides B​::​f(int);
 using B::g;
 void g(char); // OK
 using B::h;
 void h(int); // OK, D​::​h(int) hides B​::​h(int)
};
void k(D* p)
{
 p->f(1); // calls D​::​f(int)
 p->f('a'); // calls B​::​f(char)
 p->g(1); // calls B​::​g(int)
 p->g('a'); // calls D​::​g(char)
}
struct B1 {
 B1(int);
};
struct B2 {
 B2(int);
};
struct D1 : B1, B2 {
 using B1::B1;
 using B2::B2;
};
D1 d1(0); // error: ambiguous
struct D2 : B1, B2 {
 using B1::B1;
 using B2::B2;
 D2(int); // OK, D2​::​D2(int) hides B1​::​B1(int) and B2​::​B2(int)
};
D2 d2(0); // calls D2​::​D2(int)

— end example]

[Note 7: Because a using-declarator designates a base class member (and not a member subobject or a member function of a base class subobject), a using-declarator cannot be used to resolve inherited member ambiguities. [Example 8:

struct A { int x(); };
struct B : A { };
struct C : A {
 using A::x;
 int x(int);
};
struct D : B, C {
 using C::x;
 int x(double);
};
int f(D* d) {
 return d->x(); // error: overload resolution selects A​::​x, but A is an ambiguous base class
}

— end example] — end note]

A using-declaration has the usual accessibility for a member-declaration. Base-class constructors considered because of a using-declarator are accessible if they would be accessible when used to construct an object of the base class; the accessibility of the using-declaration is ignored. [Example 9:

class A {
private:
 void f(char);
public:
 void f(int);
protected:
 void g();
};
class B : public A {
 using A::f; // error: A​::​f(char) is inaccessible
public:
 using A::g; // B​::​g is a public synonym for A​::​g
};

— end example]

Every implementation shall provide for linkage to the C programming language, "C", and C++, "C++". [Example 1:

complex sqrt(complex); // C++ language linkage by default
extern "C" {
 double sqrt(double); // C language linkage
}

— end example]

Linkage specifications nest. When linkage specifications nest, the innermost one determines the language linkage. [Note 3: A linkage specification does not establish a scope. — end note] A linkage-specification shall inhabit a namespace scope. In a linkage-specification, the specified language linkage applies to the function types of all function declarators and to all functions and variables whose names have external linkage. [Example 2:

extern "C" // f1 and its function type have C language linkage;
 void f1(void(*pf)(int)); // pf is a pointer to a C function
extern "C" typedef void FUNC();
FUNC f2; // f2 has C++ language linkage and
 // its type has C language linkage
extern "C" FUNC f3; // f3 and its type have C language linkage
void (*pf2)(FUNC*); // the variable pf2 has C++ language linkage; its type
 // is “pointer to C++ function that takes one parameter of type
 // pointer to C function''
extern "C" {
 static void f4(); // the name of the function f4 has internal linkage,
 // so f4 has no language linkage; its type has C language linkage
}
extern "C" void f5() {
 extern void f4(); // OK, name linkage (internal) and function type linkage (C language linkage)
 // obtained from previous declaration.
}
extern void f4(); // OK, name linkage (internal) and function type linkage (C language linkage)
 // obtained from previous declaration.
void f6() {
 extern void f4(); // OK, name linkage (internal) and function type linkage (C language linkage)
 // obtained from previous declaration.
}

— end example] A C language linkage is ignored in determining the language linkage of class members, friend functions with a trailing requires-clause, and the function type of non-static class member functions. [Example 3:

extern "C" typedef void FUNC_c();
class C {
 void mf1(FUNC_c*); // the function mf1 and its type have C++ language linkage;
 // the parameter has type “pointer to C function''
 FUNC_c mf2; // the function mf2 and its type have C++ language linkage
 static FUNC_c* q; // the data member q has C++ language linkage;
 // its type is “pointer to C function''
};
extern "C" {
 class X {
 void mf(); // the function mf and its type have C++ language linkage
 void mf2(void(*)()); // the function mf2 has C++ language linkage;
 // the parameter has type “pointer to C function''
 };
}

— end example]

Two declarations declare the same entity if they (re)introduce the same name, one declares a function or variable with C language linkage, and the other declares such an entity or declares a variable that belongs to the global scope. [Example 4:

int x;
namespace A {
 extern "C" int f();
 extern "C" int g() { return 1; }
 extern "C" int h();
 extern "C" int x(); // error: same name as global-space object x
}
namespace B {
 extern "C" int f(); // A​::​f and B​::​f refer to the same function
 extern "C" int g() { return 1; } // error: the function g with C language linkage has two definitions
}
int A::f() { return 98; } // definition for the function f with C language linkage
extern "C" int h() { return 97; } // definition for the function h with C language linkage
 // A​::​h and ​::​h refer to the same function

— end example]

A declaration directly contained in a linkage-specification is treated as if it contains the extern specifier ([dcl.stc]) for the purpose of determining the linkage of the declared name and whether it is a definition. Such a declaration shall not specify a storage class. [Example 5:

extern "C" double f();
static double f(); // error
extern "C" int i; // declaration
extern "C" {
 int i; // definition
}
extern "C" static void g(); // error

— end example]

If an attribute-specifier contains an attribute-using-prefix, the attribute-list following that attribute-using-prefix shall not contain an attribute-scoped-token and every attribute-token in that attribute-list is treated as if its identifier were prefixed with N::, where N is the attribute-namespace specified in the attribute-using-prefix. [Note 1: This rule imposes no constraints on how an attribute-using-prefix affects the tokens in an attribute-argument-clause. — end note] [Example 1:

[[using CC: opt(1), debug]] // same as [[CC​::​opt(1), CC​::​debug]]
 void f() {}
[[using CC: opt(1)]] [[CC::debug]] // same as [[CC​::​opt(1)]] [[CC​::​debug]]
 void g() {}
[[using CC: CC::opt(1)]] // error: cannot combine using and scoped attribute token
 void h() {}

— end example]

Two consecutive left square bracket tokens shall appear only when introducing an attribute-specifier or within the balanced-token-seq of an attribute-argument-clause. [Note 6: If two consecutive left square brackets appear where an attribute-specifier is not allowed, the program is ill-formed even if the brackets match an alternative grammar production. — end note] [Example 2:

int p[10];
void f() {
 int x = 42, y[5];
 int(p[[x] { return x; }()]); // error: invalid attribute on a nested declarator-id and
 // not a function-style cast of an element of p.
 y[[] { return 2; }()] = 2; // error even though attributes are not allowed in this context.
 int i [[vendor::attr([[]])]]; // well-formed implementation-defined attribute.
}

— end example]

The combined effect of all alignment-specifiers in a declaration shall not specify an alignment that is less strict than the alignment that would be required for the entity being declared if all alignment-specifiers appertaining to that entity were omitted. [Example 1:

struct alignas(8) S {};
struct alignas(1) U {
 S s;
}; // error: U specifies an alignment that is less strict than if the alignas(1) were omitted.

— end example]

If the defining declaration of an entity has an alignment-specifier, any non-defining declaration of that entity shall either specify equivalent alignment or have no alignment-specifier. Conversely, if any declaration of an entity has an alignment-specifier, every defining declaration of that entity shall specify an equivalent alignment. No diagnostic is required if declarations of an entity have different alignment-specifiers in different translation units. [Example 2:

// Translation unit #1:
struct S { int x; } s, *p = &s;
// Translation unit #2:
struct alignas(16) S; // ill-formed, no diagnostic required: definition of S lacks alignment
extern S* p;

— end example]

[Example 3: An aligned buffer with an alignment requirement of A and holding N elements of type T can be declared as:

alignas(T) alignas(A) T buffer[N];

Specifying alignas(T) ensures that the final requested alignment will not be weaker than alignof(T), and therefore the program will not be ill-formed. — end example]

[Example 1:

/* Translation unit A. */
struct foo { int* a; int* b; };
std::atomic<struct foo *> foo_head[10];
int foo_array[10][10];
[[carries_dependency]] struct foo* f(int i) {
 return foo_head[i].load(memory_order::consume);
}
int g(int* x, int* y [[carries_dependency]]) {
 return kill_dependency(foo_array[*x][*y]);
}
/* Translation unit B. */
[[carries_dependency]] struct foo* f(int i);
int g(int* x, int* y [[carries_dependency]]);
int c = 3;
void h(int i) {
 struct foo* p;
 p = f(i);
 do_something_with(g(&c, p->a));
 do_something_with(g(p->a, &c));
}

The carries_dependency attribute on function f means that the return value carries a dependency out of f, so that the implementation need not constrain ordering upon return from f. Implementations of f and its caller may choose to preserve dependencies instead of emitting hardware memory ordering instructions (a.k.a. fences). Function g's second parameter has a carries_dependency attribute, but its first parameter does not. Therefore, function h's first call to g carries a dependency into g, but its second call does not. The implementation might need to insert a fence prior to the second call to g. — end example]

The attribute-token fallthrough may be applied to a null statement; such a statement is a fallthrough statement. No attribute-argument-clause shall be present. A fallthrough statement may only appear within an enclosing switch statement ([stmt.switch]). The next statement that would be executed after a fallthrough statement shall be a labeled statement whose label is a case label or default label for the same switch statement and, if the fallthrough statement is contained in an iteration statement, the next statement shall be part of the same execution of the substatement of the innermost enclosing iteration statement. The program is ill-formed if there is no such statement.

Recommended practice: The use of a fallthrough statement should suppress a warning that an implementation might otherwise issue for a case or default label that is reachable from another case or default label along some path of execution. Implementations should issue a warning if a fallthrough statement is not dynamically reachable.

[Example 1:

void f(int n) {
 void g(), h(), i();
 switch (n) {
 case 1:
 case 2:
 g();
 [[fallthrough]];
 case 3: // warning on fallthrough discouraged
 do {
 [[fallthrough]]; // error: next statement is not part of the same substatement execution
 } while (false);
 case 6:
 do {
 [[fallthrough]]; // error: next statement is not part of the same substatement execution
 } while (n--);
 case 7:
 while (false) {
 [[fallthrough]]; // error: next statement is not part of the same substatement execution
 }
 case 5:
 h();
 case 4: // implementation may warn on fallthrough
 i();
 [[fallthrough]]; // error
 }
}

— end example]

The attribute-tokens likely and unlikely may be applied to labels or statements. No attribute-argument-clause shall be present. The attribute-token likely shall not appear in an attribute-specifier-seq that contains the attribute-token unlikely.

Recommended practice: The use of the likely attribute is intended to allow implementations to optimize for the case where paths of execution including it are arbitrarily more likely than any alternative path of execution that does not include such an attribute on a statement or label. The use of the unlikely attribute is intended to allow implementations to optimize for the case where paths of execution including it are arbitrarily more unlikely than any alternative path of execution that does not include such an attribute on a statement or label. A path of execution includes a label if and only if it contains a jump to that label. [Note 1: Excessive usage of either of these attributes is liable to result in performance degradation. — end note]

[Example 1:

void g(int);
int f(int n) {
 if (n > 5) [[unlikely]] { // n > 5 is considered to be arbitrarily unlikely
 g(0);
 return n * 2 + 1;
 }
 switch (n) {
 case 1:
 g(1);
 [[fallthrough]];
 [[likely]] case 2: // n == 2 is considered to be arbitrarily more
 g(2); // likely than any other value of n
 break;
 }
 return 3;
}

— end example]

[Example 1:

[[maybe_unused]] void f([[maybe_unused]] bool thing1,
 [[maybe_unused]] bool thing2) {
 [[maybe_unused]] bool b = thing1 && thing2;
 assert(b);
}

Implementations should not warn that b is unused, whether or not NDEBUG is defined. — end example]

[Example 1:

struct [[nodiscard]] my_scopeguard { /* ... */ };
struct my_unique {
 my_unique() = default; // does not acquire resource
 [[nodiscard]] my_unique(int fd) { /* ... */ } // acquires resource
 ~my_unique() noexcept { /* ... */ } // releases resource, if any
 /* ... */
};
struct [[nodiscard]] error_info { /* ... */ };
error_info enable_missile_safety_mode();
void launch_missiles();
void test_missiles() {
 my_scopeguard(); // warning encouraged
 (void)my_scopeguard(), // warning not encouraged, cast to void
 launch_missiles(); // comma operator, statement continues
 my_unique(42); // warning encouraged
 my_unique(); // warning not encouraged
 enable_missile_safety_mode(); // warning encouraged
 launch_missiles();
}
error_info &foo();
void f() { foo(); } // warning not encouraged: not a nodiscard call, because neither
 // the (reference) return type nor the function is declared nodiscard

— end example]

[Example 1:

[[ noreturn ]] void f() {
 throw "error"; // OK
}
[[ noreturn ]] void q(int i) { // behavior is undefined if called with an argument <= 0
 if (i > 0)
 throw "positive";
}

— end example]

The attribute-token no_unique_address specifies that a non-static data member is a potentially-overlapping subobject ([intro.object]). No attribute-argument-clause shall be present. The attribute may appertain to a non-static data member other than a bit-field.

[Note 1: The non-static data member can share the address of another non-static data member or that of a base class, and any padding that would normally be inserted at the end of the object can be reused as storage for other members. — end note] [Example 1:

template<typename Key, typename Value,
 typename Hash, typename Pred, typename Allocator>
class hash_map {
 [[no_unique_address]] Hash hasher;
 [[no_unique_address]] Pred pred;
 [[no_unique_address]] Allocator alloc;
 Bucket *buckets;
 // ...
public:
 // ...
};

Here, hasher, pred, and alloc could have the same address as buckets if their respective types are all empty. — end example]

[Example 1: Translation unit #1:

export module A;
export import :Foo;
export int baz();

Translation unit #2:

export module A:Foo;
import :Internals;
export int foo() { return 2 * (bar() + 1); }

Translation unit #3:

module A:Internals;
int bar();

Translation unit #4:

module A;
import :Internals;
int bar() { return baz() - 10; }
int baz() { return 30; }

Module A contains four translation units: a primary module interface unit,a module partition A:Foo, which is a module interface unit forming part of the interface of module A,a module partition A:Internals, which does not contribute to the external interface of module A, anda module implementation unit providing a definition of bar and baz, which cannot be imported because it does not have a partition name. — end example]

[Example 1: Source file "a.h":

export int x;

Translation unit #1:

module;
#include "a.h" // error: declaration of x is not in the
 // purview of a module interface unit
export module M;
export namespace {} // error: namespace has internal linkage
namespace {
 export int a2; // error: export of name with internal linkage
}
export static int b; // error: b explicitly declared static
export int f(); // OK
export namespace N { } // OK
export using namespace N; // OK

— end example]

If an exported declaration is a using-declaration ([namespace.udecl]) and is not within a header unit, all entities to which all of the using-declarators ultimately refer (if any) shall have been introduced with a name having external linkage. [Example 2: Source file "b.h":

int f();

Importable header "c.h":

int g();

Translation unit #1:

export module X;
export int h();

Translation unit #2:

module;
#include "b.h"
export module M;
import "c.h";
import X;
export using ::f, ::g, ::h; // OK
struct S;
export using ::S; // error: S has module linkage
namespace N {
 export int h();
 static int h(int); // #1
}
export using N::h; // error: #1 has internal linkage

— end example] [Note 2: These constraints do not apply to type names introduced by typedef declarations and alias-declarations. [Example 3:

export module M;
struct S;
export using T = S; // OK, exports name T denoting type S

— end example] — end note]

A redeclaration of an entity X is implicitly exported if X was introduced by an exported declaration; otherwise it shall not be exported. [Example 4:

export module M;
struct S { int n; };
typedef S S;
export typedef S S; // OK, does not redeclare an entity
export struct S; // error: exported declaration follows non-exported declaration

— end example]

[Note 3: Names introduced by exported declarations have either external linkage or no linkage; see [basic.link]. Namespace-scope declarations exported by a module can be found by name lookup in any translation unit importing that module ([basic.lookup]). Class and enumeration member names can be found by name lookup in any context in which a definition of the type is reachable. — end note] [Example 5: Interface unit of M:

export module M;
export struct X {
 static void f();
 struct Y { };
};
namespace {
 struct S { };
}
export void f(S); // OK
struct T { };
export T id(T); // OK
export struct A; // A exported as incomplete
export auto rootFinder(double a) {
 return [=](double x) { return (x + a/x)/2; };
}
export const int n = 5; // OK, n has external linkage

Implementation unit of M:

module M;
struct A {
 int value;
};

Main program:

import M;
int main() {
 X::f(); // OK, X is exported and definition of X is reachable
 X::Y y; // OK, X​::​Y is exported as a complete type
 auto f = rootFinder(2); // OK
 return A{45}.value; // error: A is incomplete
}

— end example]

[Note 4: Declarations in an exported namespace-definition or in an exported linkage-specification ([dcl.link]) are exported and subject to the rules of exported declarations. [Example 6:

export module M;
int g;
export namespace N {
 int x; // OK
 using ::g; // error: ​::​g has module linkage
}

— end example] — end note]

A module implementation unit shall not be exported. [Example 1: Translation unit #1:

module M:Part;

Translation unit #2:

export module M;
export import :Part; // error: exported partition :Part is an implementation unit

— end example]

A translation unit has an interface dependency on a translation unit U if it contains a declaration (possibly a module-declaration) that imports U or if it has an interface dependency on a translation unit that has an interface dependency on U. A translation unit shall not have an interface dependency on itself. [Example 3: Interface unit of M1:

export module M1;
import M2;

Interface unit of M2:

export module M2;
import M3;

Interface unit of M3:

export module M3;
import M1; // error: cyclic interface dependency M3 →M1 →M2 →M3

— end example]

[Example 1:

const int size = 2;
int ary1[size]; // unspecified whether size is decl-reachable from ary1
constexpr int identity(int x) { return x; }
int ary2[identity(2)]; // unspecified whether identity is decl-reachable from ary2
template<typename> struct S;
template<typename, int> struct S2;
constexpr int g(int);
template<typename T, int N>
S<S2<T, g(N)>> f(); // S, S2, g, and ​::​ are decl-reachable from f
template<int N>
void h() noexcept(g(N) == N); // g and ​::​ are decl-reachable from h

— end example]

[Example 2: Source file "foo.h":

namespace N {
 struct X {};
 int d();
 int e();
 inline int f(X, int = d()) { return e(); }
 int g(X);
 int h(X);
}

Module M interface:

module;
#include "foo.h"
export module M;
template<typename T> int use_f() {
 N::X x; // N​::​X, N, and ​::​ are decl-reachable from use_f
 return f(x, 123); // N​::​f is decl-reachable from use_f,
 // N​::​e is indirectly decl-reachable from use_f
 // because it is decl-reachable from N​::​f, and
 // N​::​d is decl-reachable from use_f
 // because it is decl-reachable from N​::​f
 // even though it is not used in this call
}
template<typename T> int use_g() {
 N::X x; // N​::​X, N, and ​::​ are decl-reachable from use_g
 return g((T(), x)); // N​::​g is not decl-reachable from use_g
}
template<typename T> int use_h() {
 N::X x; // N​::​X, N, and ​::​ are decl-reachable from use_h
 return h((T(), x)); // N​::​h is not decl-reachable from use_h, but
 // N​::​h is decl-reachable from use_h<int>
}
int k = use_h<int>();
 // use_h<int> is decl-reachable from k, so
 // N​::​h is decl-reachable from k

Module M implementation:

module M;
int a = use_f<int>(); // OK
int b = use_g<int>(); // error: no viable function for call to g;
 // g is not decl-reachable from purview of
 // module M's interface, so is discarded
int c = use_h<int>(); // OK

— end example]

A private-module-fragment shall appear only in a primary module interface unit ([module.unit]). A module unit with a private-module-fragment shall be the only module unit of its module; no diagnostic is required.

[Note 1: A private-module-fragment ends the portion of the module interface unit that can affect the behavior of other translation units. A private-module-fragment allows a module to be represented as a single translation unit without making all of the contents of the module reachable to importers. The presence of a private-module-fragment affects: the point by which the definition of an inline function or variable is required ([dcl.inline]),the point by which the definition of an exported function with a placeholder return type is required ([dcl.spec.auto]),whether a declaration is required not to be an exposure ([basic.link]),where definitions for inline functions and templates must appear ([basic.def.odr], [dcl.inline], [temp.pre]),the instantiation contexts of templates instantiated before it ([module.context]), andthe reachability of declarations within it ([module.reach]). — end note]

[Example 1:

export module A;
export inline void fn_e(); // error: exported inline function fn_e not defined
 // before private module fragment
inline void fn_m(); // error: non-exported inline function fn_m not defined
static void fn_s();
export struct X;
export void g(X *x) {
 fn_s(); // OK, call to static function in same translation unit
}
export X *factory(); // OK
module :private;
struct X {}; // definition not reachable from importers of A
X *factory() {
 return new X ();
}
void fn_e() {}
void fn_m() {}
void fn_s() {}

— end example]

[Example 1: Translation unit #1:

export module stuff;
export template<typename T, typename U> void foo(T, U u) { auto v = u; }
export template<typename T, typename U> void bar(T, U u) { auto v = *u; }

Translation unit #2:

export module M1;
import "defn.h"; // provides struct X {};
import stuff;
export template<typename T> void f(T t) {
 X x;
 foo(t, x);
}

Translation unit #3:

export module M2;
import "decl.h"; // provides struct X; (not a definition)
import stuff;
export template<typename T> void g(T t) {
 X *x;
 bar(t, x);
}

Translation unit #4:

import M1;
import M2;
void test() {
 f(0);
 g(0);
}

The call to f(0) is valid; the instantiation context of foo<int, X> comprises the point at the end of translation unit #1,the point at the end of translation unit #2, andthe point of the call to f(0), so the definition of X is reachable ([module.reach]).It is unspecified whether the call to g(0) is valid: the instantiation context of bar<int, X> comprises the point at the end of translation unit #1,the point at the end of translation unit #3, andthe point of the call to g(0), so the definition of X need not be reachable, as described in [module.reach]. — end example]

The accumulated properties of all reachable declarations of an entity within a context determine the behavior of the entity within that context. [Note 4: These reachable semantic properties include type completeness, type definitions, initializers, default arguments of functions or template declarations, attributes, names bound, etc. Since default arguments are evaluated in the context of the call expression, the reachable semantic properties of the corresponding parameter types apply in that context. [Example 1: Translation unit #1:

export module M:A;
export struct B;

Translation unit #2:

module M:B;
struct B {
 operator int();
};

Translation unit #3:

module M:C;
import :A;
B b1; // error: no reachable definition of struct B

Translation unit #4:

export module M;
export import :A;
import :B;
B b2;
export void f(B b = B());

Translation unit #5:

import M;
B b3; // error: no reachable definition of struct B
void g() { f(); } // error: no reachable definition of struct B

— end example] — end note]

[Note 5: Declarations of an entity can be reachable even where they cannot be found by name lookup. — end note] [Example 2: Translation unit #1:

export module A;
struct X {};
export using Y = X;

Translation unit #2:

import A;
Y y; // OK, definition of X is reachable
X x; // error: X not visible to unqualified lookup

— end example]

If a class-head-name contains a nested-name-specifier, the class-specifier shall not inhabit a class scope. If its class-name is an identifier, the class-specifier shall correspond to one or more declarations nominable in the class, class template, or namespace to which the nested-name-specifier refers; they shall all have the same target scope, and the target scope of the class-specifier is that scope. [Example 1:

namespace N {
 template<class>
 struct A {
 struct B;
 };
}
using N::A;
template<class T> struct A<T>::B {}; // OK
template<> struct A<void> {}; // OK

— end example]

If a class is marked with the class-virt-specifier final and it appears as a class-or-decltype in a base-clause ([class.derived]), the program is ill-formed. Whenever a class-key is followed by a class-head-name, the identifier final, and a colon or left brace, final is interpreted as a class-virt-specifier. [Example 2:

struct A;
struct A final {}; // OK, definition of struct A,
 // not value-initialization of variable final
struct X {
 struct C { constexpr operator int() { return 5; } };
 struct B final : C{}; // OK, definition of nested class B,
 // not declaration of a bit-field member final
};

— end example]

[Example 1:

struct B { int i; }; // standard-layout class
struct C : B { }; // standard-layout class
struct D : C { }; // standard-layout class
struct E : D { char : 4; }; // not a standard-layout class
struct Q {};
struct S : Q { };
struct T : Q { };
struct U : S, T { }; // not a standard-layout class

— end example]

[Example 2:

struct N { // neither trivial nor standard-layout
 int i;
 int j;
 virtual ~N();
};
struct T { // trivial but not standard-layout
 int i;
private:
 int j;
};
struct SL { // standard-layout but not trivial
 int i;
 int j;
 ~SL();
};
struct POD { // both trivial and standard-layout
 int i;
 int j;
};

— end example]

A class definition introduces a new type. [Example 1:

struct X { int a; };
struct Y { int a; };
X a1;
Y a2;
int a3;

declares three variables of three different types. This implies that

a1 = a2; // error: Y assigned to X
a1 = a3; // error: int assigned to X

are type mismatches, and that

int f(X);
int f(Y);

declare overloads ([over]) named f and not simply a single function f twice. For the same reason,

struct S { int a; };
struct S { int a; }; // error: double definition

is ill-formed because it defines S twice. — end example]

[Note 1: It can be necessary to use an elaborated-type-specifier to refer to a class that belongs to a scope in which its name is also bound to a variable, function, or enumerator ([basic.lookup.elab]). [Example 2:

struct stat {
 // ...
};
stat gstat; // use plain stat to define variable
int stat(struct stat*); // stat now also names a function
void f() {
 struct stat* ps; // struct prefix needed to name struct stat
 stat(ps); // call stat function
}

— end example] An elaborated-type-specifier can also be used to declare an identifier as a class-name. [Example 3:

struct s { int a; };
void g() {
 struct s; // hide global struct s with a block-scope declaration
 s* p; // refer to local struct s
 struct s { char* p; }; // define local struct s
 struct s; // redeclaration, has no effect
}

— end example] Such declarations allow definition of classes that refer to each other. [Example 4:

class Vector;
class Matrix {
 // ...
 friend Vector operator*(const Matrix&, const Vector&);
};
class Vector {
 // ...
 friend Vector operator*(const Matrix&, const Vector&);
};

Declaration of friends is described in [class.friend], operator functions in [over.oper]. — end example] — end note]

[Note 2: An elaborated-type-specifier ([dcl.type.elab]) can also be used as a type-specifier as part of a declaration. It differs from a class declaration in that it can refer to an existing class of the given name. — end note] [Example 5:

struct s { int a; };
void g(int s) {
 struct s* p = new struct s; // global s
 p->a = s; // parameter s
}

— end example]

[Note 3: The declaration of a class name takes effect immediately after the identifier is seen in the class definition or elaborated-type-specifier. For example,

class A * A;

first specifies A to be the name of a class and then redefines it as the name of a pointer to an object of that class. This means that the elaborated form class A must be used to refer to the class. Such artistry with names can be confusing and is best avoided. — end note]

In a member-declarator, an = immediately following the declarator is interpreted as introducing a pure-specifier if the declarator-id has function type, otherwise it is interpreted as introducing a brace-or-equal-initializer. [Example 1:

struct S {
 using T = void();
 T * p = 0; // OK, brace-or-equal-initializer
 virtual T f = 0; // OK, pure-specifier
};

— end example]

In a member-declarator for a bit-field, the constant-expression is parsed as the longest sequence of tokens that could syntactically form a constant-expression. [Example 2:

int a;
const int b = 0;
struct S {
 int x1 : 8 = 42; // OK, "= 42" is brace-or-equal-initializer
 int x2 : 8 { 42 }; // OK, "{ 42 }" is brace-or-equal-initializer
 int y1 : true ? 8 : a = 42; // OK, brace-or-equal-initializer is absent
 int y2 : true ? 8 : b = 42; // error: cannot assign to const int
 int y3 : (true ? 8 : b) = 42; // OK, "= 42" is brace-or-equal-initializer
 int z : 1 || new int { 0 }; // OK, brace-or-equal-initializer is absent
};

— end example]

[Example 3: A simple example of a class definition is

struct tnode {
 char tword[20];
 int count;
 tnode* left;
 tnode* right;
};

which contains an array of twenty characters, an integer, and two pointers to objects of the same type. Once this definition has been given, the declaration

tnode s, *sp;

declares s to be a tnode and sp to be a pointer to a tnode. With these declarations, sp->count refers to the count member of the object to which sp points; s.left refers to the left subtree pointer of the object s; and s.right->tword[0] refers to the initial character of the tword member of the right subtree of s. — end example]

The common initial sequence of two standard-layout struct ([class.prop]) types is the longest sequence of non-static data members and bit-fields in declaration order, starting with the first such entity in each of the structs, such that corresponding entities have layout-compatible types ([basic.types]),corresponding entities have the same alignment requirements ([basic.align]),either both entities are declared with the no_unique_address attribute ([dcl.attr.nouniqueaddr]) or neither is, andeither both entities are bit-fields with the same width or neither is a bit-field. [Example 4:

struct A { int a; char b; };
struct B { const int b1; volatile char b2; };
struct C { int c; unsigned : 0; char b; };
struct D { int d; char b : 4; };
struct E { unsigned int e; char b; };

The common initial sequence of A and B comprises all members of either class. The common initial sequence of A and C and of A and D comprises the first member in each case. The common initial sequence of A and E is empty. — end example]

In a standard-layout union with an active member of struct type T1, it is permitted to read a non-static data member m of another union member of struct type T2 provided m is part of the common initial sequence of T1 and T2; the behavior is as if the corresponding member of T1 were nominated. [Example 5:

struct T1 { int a, b; };
struct T2 { int c; double d; };
union U { T1 t1; T2 t2; };
int f() {
 U u = { { 1, 2 } }; // active member is t1
 return u.t2.c; // OK, as if u.t1.a were nominated
}

— end example] [Note 10: Reading a volatile object through a glvalue of non-volatile type has undefined behavior ([dcl.type.cv]). — end note]

[Example 1:

struct X {
 typedef int T;
 static T count;
 void f(T);
};
void X::f(T t = count) { }

The definition of the member function f of class X inhabits the global scope; the notation X:: f indicates that the function f is a member of class X and in the scope of class X. In the function definition, the parameter type T refers to the typedef member T declared in class X and the default argument count refers to the static data member count declared in class X. — end example]

[Note 2: A member function can be declared (but not defined) using a typedef for a function type. The resulting member function has exactly the same type as it would have if the function declarator were provided explicitly, see [dcl.fct]. For example,

typedef void fv();
typedef void fvc() const;
struct S {
 fv memfunc1; // equivalent to: void memfunc1();
 void memfunc2();
 fvc memfunc3; // equivalent to: void memfunc3() const;
};
fv S::* pmfv1 = &S::memfunc1;
fv S::* pmfv2 = &S::memfunc2;
fvc S::* pmfv3 = &S::memfunc3;

Also see [temp.arg]. — end note]

When an id-expression ([expr.prim.id]) that is neither part of a class member access syntax ([expr.ref]) nor the unparenthesized operand of the unary & operator ([expr.unary.op]) is used where the current class is X ([expr.prim.this]), if name lookup ([basic.lookup]) resolves the name in the id-expression to a non-static non-type member of some class C, and if either the id-expression is potentially evaluated or C is X or a base class of X, the id-expression is transformed into a class member access expression ([expr.ref]) using (*this) as the postfix-expression to the left of the. operator. [Note 1: If C is not X or a base class of X, the class member access expression is ill-formed. — end note] This transformation does not apply in the template definition context ([temp.dep.type]). [Example 1:

struct tnode {
 char tword[20];
 int count;
 tnode* left;
 tnode* right;
 void set(const char*, tnode* l, tnode* r);
};
void tnode::set(const char* w, tnode* l, tnode* r) {
 count = strlen(w)+1;
 if (sizeof(tword)<=count)
 perror("tnode string too long");
 strcpy(tword,w);
 left = l;
 right = r;
}
void f(tnode n1, tnode n2) {
 n1.set("abc",&n2,0);
 n2.set("def",0,0);
}

In the body of the member function tnode:: set, the member names tword, count, left, and right refer to members of the object for which the function is called. Thus, in the call n1.set("abc",&n2,0), tword refers to n1.tword, and in the call n2.set("def",0,0), it refers to n2.tword. The functions strlen, perror, and strcpy are not members of the class tnode and should be declared elsewhere. — end example]

Programs may explicitly refer to implicitly-declared special member functions. [Example 1: A program may explicitly call or form a pointer to member to an implicitly-declared special member function.

struct A { }; // implicitly declared A​::​operator=
struct B : A {
 B& operator=(const B &);
};
B& B::operator=(const B& s) {
 this->A::operator=(s); // well-formed
 return *this;
}

— end example]

A declarator declares a constructor if it is a function declarator ([dcl.fct]) of the form ptr-declarator (parameter-declaration-clause) noexcept-specifieropt attribute-specifier-seqopt where the ptr-declarator consists solely of an id-expression, an optional attribute-specifier-seq, and optional surrounding parentheses, and the id-expression has one of the following forms: in a friend declaration ([class.friend]), the id-expression is a qualified-id that names a constructor ([class.qual]);otherwise, in a member-declaration that belongs to the member-specification of a class or class template, the id-expression is the injected-class-name ([class.pre]) of the immediately-enclosing entity;otherwise, the id-expression is a qualified-id whose unqualified-id is the injected-class-name of its lookup context. Constructors do not have names. In a constructor declaration, each decl-specifier in the optional decl-specifier-seq shall be friend, inline, constexpr, consteval, or an explicit-specifier. [Example 1:

struct S {
 S(); // declares the constructor
};
S::S() { } // defines the constructor

— end example]

A constructor is used to initialize objects of its class type. [Note 1: Because constructors do not have names, they are never found during unqualified name lookup; however an explicit type conversion using the functional notation ([expr.type.conv]) will cause a constructor to be called to initialize an object. The syntax looks like an explicit call of the constructor. — end note] [Example 2:

complex zz = complex(1,2.3);
cprint( complex(7.8,1.2) );

— end example] [Note 2: For initialization of objects of class type see [class.init]. — end note]

A non-template constructor for class X is a copy constructor if its first parameter is of type X&, const X&, volatile X& or const volatile X&, and either there are no other parameters or else all other parameters have default arguments ([dcl.fct.default]). [Example 1: X:: X(const X&) and X:: X(X&,int=1) are copy constructors.

struct X {
 X(int);
 X(const X&, int = 1);
};
X a(1); // calls X(int);
X b(a, 0); // calls X(const X&, int);
X c = b; // calls X(const X&, int);

— end example]

A non-template constructor for class X is a move constructor if its first parameter is of type X&&, const X&&, volatile X&&, or const volatile X&&, and either there are no other parameters or else all other parameters have default arguments ([dcl.fct.default]). [Example 2: Y:: Y(Y&&) is a move constructor.

struct Y {
 Y(const Y&);
 Y(Y&&);
};
extern Y f(int);
Y d(f(1)); // calls Y(Y&&)
Y e = d; // calls Y(const Y&)

— end example]

[Note 1: All forms of copy/move constructor can be declared for a class. [Example 3:

struct X {
 X(const X&);
 X(X&); // OK
 X(X&&);
 X(const X&&); // OK, but possibly not sensible
};

— end example] — end note]

[Note 2: If a class X only has a copy constructor with a parameter of type X&, an initializer of type const X or volatile X cannot initialize an object of type cv X. [Example 4:

struct X {
 X(); // default constructor
 X(X&); // copy constructor with a non-const parameter
};
const X cx;
X x = cx; // error: X​::​X(X&) cannot copy cx into x

— end example] — end note]

A declaration of a constructor for a class X is ill-formed if its first parameter is of type cv X and either there are no other parameters or else all other parameters have default arguments. A member function template is never instantiated to produce such a constructor signature. [Example 5:

struct S {
 template<typename T> S(T);
 S();
};
S g;
void h() {
 S a(g); // does not instantiate the member template to produce S​::​S<S>(S);
 // uses the implicitly declared copy constructor
}

— end example]

A user-declared copy assignment operator X:: operator= is a non-static non-template member function of class X with exactly one non-object parameter of type X, X&, const X&, volatile X&, or const volatile X&. [Note 1: An overloaded assignment operator must be declared to have only one parameter; see [over.ass]. — end note] [Note 2: More than one form of copy assignment operator can be declared for a class. — end note] [Note 3: If a class X only has a copy assignment operator with a parameter of type X&, an expression of type const X cannot be assigned to an object of type X. [Example 1:

struct X {
 X();
 X& operator=(X&);
};
const X cx;
X x;
void f() {
 x = cx; // error: X​::​operator=(X&) cannot assign cx into x
}

— end example] — end note]

If the definition of a class X does not explicitly declare a move assignment operator, one will be implicitly declared as defaulted if and only if X does not have a user-declared copy constructor,X does not have a user-declared move constructor,X does not have a user-declared copy assignment operator, andX does not have a user-declared destructor.[Example 2: The class definition

struct S {
 int a;
 S& operator=(const S&) = default;
};

will not have a default move assignment operator implicitly declared because the copy assignment operator has been user-declared. The move assignment operator may be explicitly defaulted.

struct S {
 int a;
 S& operator=(const S&) = default;
 S& operator=(S&&) = default;
};

— end example]

The implicitly-defined copy/move assignment operator for a non-union class X performs memberwise copy/move assignment of its subobjects. The direct base classes of X are assigned first, in the order of their declaration in the base-specifier-list, and then the immediate non-static data members of X are assigned, in the order in which they were declared in the class definition. Let x be either the parameter of the function or, for the move operator, an xvalue referring to the parameter. Each subobject is assigned in the manner appropriate to its type: if the subobject is of class type, as if by a call to operator= with the subobject as the object expression and the corresponding subobject of x as a single function argument (as if by explicit qualification; that is, ignoring any possible virtual overriding functions in more derived classes);if the subobject is an array, each element is assigned, in the manner appropriate to the element type;if the subobject is of scalar type, the built-in assignment operator is used.It is unspecified whether subobjects representing virtual base classes are assigned more than once by the implicitly-defined copy/move assignment operator. [Example 3:

struct V { };
struct A : virtual V { };
struct B : virtual V { };
struct C : B, A { };

It is unspecified whether the virtual base class subobject V is assigned twice by the implicitly-defined copy/move assignment operator for C. — end example]

In an explicit destructor call, the destructor is specified by a ~ followed by a type-name or decltype-specifier that denotes the destructor's class type. The invocation of a destructor is subject to the usual rules for member functions ([class.mfct]); that is, if the object is not of the destructor's class type and not of a class derived from the destructor's class type (including when the destructor is invoked via a null pointer value), the program has undefined behavior. [Note 7: Invoking delete on a null pointer does not call the destructor; see [expr.delete]. — end note] [Example 1:

struct B {
 virtual ~B() { }
};
struct D : B {
 ~D() { }
};
D D_object;
typedef B B_alias;
B* B_ptr = &D_object;
void f() {
 D_object.B::~B(); // calls B's destructor
 B_ptr->~B(); // calls D's destructor
 B_ptr->~B_alias(); // calls D's destructor
 B_ptr->B_alias::~B(); // calls B's destructor
 B_ptr->B_alias::~B_alias(); // calls B's destructor
}

— end example] [Note 8: An explicit destructor call must always be written using a member access operator ([expr.ref]) or a qualified-id ([expr.prim.id.qual]); in particular, the unary-expression ~X() in a member function is not an explicit destructor call ([expr.unary.op]). — end note]

[Note 9: Explicit calls of destructors are rarely needed. One use of such calls is for objects placed at specific addresses using a placement new-expression. Such use of explicit placement and destruction of objects can be necessary to cope with dedicated hardware resources and for writing memory management facilities. For example,

void* operator new(std::size_t, void* p) { return p; }
struct X {
 X(int);
 ~X();
};
void f(X* p);
void g() { // rare, specialized use:
 char* buf = new char[sizeof(X)];
 X* p = new(buf) X(222); // use buf[] and initialize
 f(p);
 p->X::~X(); // cleanup
}

— end note]

[Note 10: The notation for explicit call of a destructor can be used for any scalar type name ([expr.prim.id.dtor]). Allowing this makes it possible to write code without having to know if a destructor exists for a given type. For example:

typedef int I;
I* p;
p->I::~I();

— end note]

At most one user-defined conversion (constructor or conversion function) is implicitly applied to a single value. [Example 1:

struct X {
 operator int();
};
struct Y {
 operator X();
};
Y a;
int b = a; // error: no viable conversion (a.operator X().operator int() not considered)
int c = X(a); // OK, a.operator X().operator int()

— end example]

A constructor that is not explicit ([dcl.fct.spec]) specifies a conversion from the types of its parameters (if any) to the type of its class. Such a constructor is called a converting constructor. [Example 1:

struct X {
 X(int);
 X(const char*, int =0);
 X(int, int);
};
void f(X arg) {
 X a = 1; // a = X(1)
 X b = "Jessie"; // b = X("Jessie",0)
 a = 2; // a = X(2)
 f(3); // f(X(3))
 f({1, 2}); // f(X(1,2))
}

— end example]

[Note 1: An explicit constructor constructs objects just like non-explicit constructors, but does so only where the direct-initialization syntax ([dcl.init]) or where casts ([expr.static.cast], [expr.cast]) are explicitly used; see also [over.match.copy]. A default constructor can be an explicit constructor; such a constructor will be used to perform default-initialization or value-initialization ([dcl.init]). [Example 2:

struct Z {
 explicit Z();
 explicit Z(int);
 explicit Z(int, int);
};
Z a; // OK, default-initialization performed
Z b{}; // OK, direct initialization syntax used
Z c = {}; // error: copy-list-initialization
Z a1 = 1; // error: no implicit conversion
Z a3 = Z(1); // OK, direct initialization syntax used
Z a2(1); // OK, direct initialization syntax used
Z* p = new Z(1); // OK, direct initialization syntax used
Z a4 = (Z)1; // OK, explicit cast used
Z a5 = static_cast<Z>(1); // OK, explicit cast used
Z a6 = { 3, 4 }; // error: no implicit conversion

— end example] — end note]

A non-explicit copy/move constructor ([class.copy.ctor]) is a converting constructor. [Note 2: An implicitly-declared copy/move constructor is not an explicit constructor; it can be called for implicit type conversions. — end note]

A conversion function is never used to convert a (possibly cv-qualified) object to the (possibly cv-qualified) same object type (or a reference to it), to a (possibly cv-qualified) base class of that type (or a reference to it), or to cv void. [Example 1:

struct X {
 operator int();
 operator auto() -> short; // error: trailing return type
};
void f(X a) {
 int i = int(a);
 i = (int)a;
 i = a;
}

In all three cases the value assigned will be converted by X:: operator int(). — end example]

A conversion function may be explicit ([dcl.fct.spec]), in which case it is only considered as a user-defined conversion for direct-initialization ([dcl.init]). Otherwise, user-defined conversions are not restricted to use in assignments and initializations. [Example 2:

class Y { };
struct Z {
 explicit operator Y() const;
};
void h(Z z) {
 Y y1(z); // OK, direct-initialization
 Y y2 = z; // error: no conversion function candidate for copy-initialization
 Y y3 = (Y)z; // OK, cast notation
}
void g(X a, X b) {
 int i = (a) ? 1+a : 0;
 int j = (a&&b) ? a+b : i;
 if (a) {
 }
}

— end example]

[Note 2: A conversion function in a derived class hides only conversion functions in base classes that convert to the same type. A conversion function template with a dependent return type hides only templates in base classes that correspond to it ([class.member.lookup]); otherwise, it hides and is hidden as a non-template function. Function overload resolution ([over.match.best]) selects the best conversion function to perform the conversion. [Example 5:

struct X {
 operator int();
};
struct Y : X {
 operator char();
};
void f(Y& a) {
 if (a) { // error: ambiguous between X​::​operator int() and Y​::​operator char()
 }
}

— end example] — end note]

A conversion function template shall not have a deduced return type ([dcl.spec.auto]). [Example 6:

struct S {
 operator auto() const { return 10; } // OK
 template<class T>
 operator auto() const { return 1.2; } // error: conversion function template
};

— end example]

A static member s of class X may be referred to using the qualified-id expression X:: s; it is not necessary to use the class member access syntax ([expr.ref]) to refer to a static member. A static member may be referred to using the class member access syntax, in which case the object expression is evaluated. [Example 1:

struct process {
 static void reschedule();
};
process& g();
void f() {
 process::reschedule(); // OK, no object necessary
 g().reschedule(); // g() is called
}

— end example]

Static members obey the usual class member access rules ([class.access]). When used in the declaration of a class member, the static specifier shall only be used in the member declarations that appear within the member-specification of the class definition. [Note 1: It cannot be specified in member declarations that appear in namespace scope. — end note]

The declaration of a non-inline static data member in its class definition is not a definition and may be of an incomplete type other than cv void. [Note 1: The initializer in the definition of a static data member is in the scope of its class ([basic.scope.class]). — end note] [Example 1:

class process {
 static process* run_chain;
 static process* running;
};
process* process::running = get_main();
process* process::run_chain = running;

The definition of the static data member run_chain of class process inhabits the global scope; the notation process:: run_chain indicates that the member run_chain is a member of class process and in the scope of class process. In the static data member definition, the initializer expression refers to the static data member running of class process. — end example][Note 2: Once the static data member has been defined, it exists even if no objects of its class have been created. [Example 2: In the example above, run_chain and running exist even if no objects of class process are created by the program. — end example] The initialization and destruction of static data members is described in [basic.start.static], [basic.start.dynamic], and [basic.start.term]. — end note]

If a value of integral type (other than bool) is stored into a bit-field of width N and the value would be representable in a hypothetical signed or unsigned integer type with width N and the same signedness as the bit-field's type, the original value and the value of the bit-field compare equal. If the value true or false is stored into a bit-field of type bool of any size (including a one bit bit-field), the original bool value and the value of the bit-field compare equal. If a value of an enumeration type is stored into a bit-field of the same type and the width is large enough to hold all the values of that enumeration type ([dcl.enum]), the original value and the value of the bit-field compare equal. [Example 1:

enum BOOL { FALSE=0, TRUE=1 };
struct A {
 BOOL b:1;
};
A a;
void f() {
 a.b = TRUE;
 if (a.b == TRUE) // yields true
 { /* ... */ }
}

— end example]

[Example 1:

class Arena;
struct B {
 void* operator new(std::size_t, Arena*);
};
struct D1 : B {
};
Arena* ap;
void foo(int i) {
 new (ap) D1; // calls B​::​operator new(std​::​size_t, Arena*)
 new D1[i]; // calls ​::​operator new[](std​::​size_t)
 new D1; // error: ​::​operator new(std​::​size_t) hidden
}

— end example]

Any deallocation function for a class X is a static member (even if not explicitly declared static). [Example 2:

class X {
 void operator delete(void*);
 void operator delete[](void*, std::size_t);
};
class Y {
 void operator delete(void*, std::size_t);
 void operator delete[](void*);
};

— end example]

Since member allocation and deallocation functions are static they cannot be virtual. [Note 1: However, when the cast-expression of a delete-expression refers to an object of class type with a virtual destructor, because the deallocation function is chosen by the destructor of the dynamic type of the object, the effect is the same in that case. For example,

struct B {
 virtual ~B();
 void operator delete(void*, std::size_t);
};
struct D : B {
 void operator delete(void*);
};
struct E : B {
 void log_deletion();
 void operator delete(E *p, std::destroying_delete_t) {
 p->log_deletion();
 p->~E();
 ::operator delete(p);
 }
};
void f() {
 B* bp = new D;
 delete bp; // 1: uses D​::​operator delete(void*)
 bp = new E;
 delete bp; // 2: uses E​::​operator delete(E*, std​::​destroying_delete_t)
}

Here, storage for the object of class D is deallocated by D:: operator delete(), and the object of class E is destroyed and its storage is deallocated by E:: operator delete(), due to the virtual destructor. — end note] [Note 2: Virtual destructors have no effect on the deallocation function actually called when the cast-expression of a delete-expression refers to an array of objects of class type. For example,

struct B {
 virtual ~B();
 void operator delete[](void*, std::size_t);
};
struct D : B {
 void operator delete[](void*, std::size_t);
};
void f(int i) {
 D* dp = new D[i];
 delete [] dp; // uses D​::​operator delete[](void*, std​::​size_t)
 B* bp = new D[i];
 delete[] bp; // undefined behavior
}

— end note]

A class can be declared within another class. A class declared within another is called a nested class. [Note 1: See [expr.prim.id] for restrictions on the use of non-static data members and non-static member functions. — end note][Example 1:

int x;
int y;
struct enclose {
 int x;
 static int s;
 struct inner {
 void f(int i) {
 int a = sizeof(x); // OK, operand of sizeof is an unevaluated operand
 x = i; // error: assign to enclose​::​x
 s = i; // OK, assign to enclose​::​s
 ::x = i; // OK, assign to global x
 y = i; // OK, assign to global y
 }
 void g(enclose* p, int i) {
 p->x = i; // OK, assign to enclose​::​x
 }
 };
};
inner* p = 0; // error: inner not found

— end example]

[Note 2: Nested classes can be defined either in the enclosing class or in an enclosing namespace; member functions and static data members of a nested class can be defined either in the nested class or in an enclosing namespace scope. [Example 2:

struct enclose {
 struct inner {
 static int x;
 void f(int i);
 };
};
int enclose::inner::x = 1;
void enclose::inner::f(int i) { /* ... */ }
class E {
 class I1; // forward declaration of nested class
 class I2;
 class I1 { }; // definition of nested class
};
class E::I2 { }; // definition of nested class

— end example] — end note]

A friend function ([class.friend]) defined within a nested class has no special access rights to members of an enclosing class.

A union can have member functions (including constructors and destructors), but it shall not have virtual ([class.virtual]) functions. A union shall not have base classes. A union shall not be used as a base class. If a union contains a non-static data member of reference type the program is ill-formed. [Note 3: Absent default member initializers ([class.mem]), if any non-static data member of a union has a non-trivial default constructor ([class.default.ctor]), copy constructor, move constructor ([class.copy.ctor]), copy assignment operator, move assignment operator ([class.copy.assign]), or destructor ([class.dtor]), the corresponding member function of the union must be user-provided or it will be implicitly deleted ([dcl.fct.def.delete]) for the union. [Example 1: Consider the following union:

union U {
 int i;
 float f;
 std::string s;
};

Since std:: string ([string.classes]) declares non-trivial versions of all of the special member functions, U will have an implicitly deleted default constructor, copy/move constructor, copy/move assignment operator, and destructor. To use U, some or all of these member functions must be user-provided. — end example] — end note]

When the left operand of an assignment operator involves a member access expression ([expr.ref]) that nominates a union member, it may begin the lifetime of that union member, as described below. For an expression E, define the set S(E) of subexpressions of E as follows: If E is of the form A.B, S(E) contains the elements of S(A), and also contains A.B if B names a union member of a non-class, non-array type, or of a class type with a trivial default constructor that is not deleted, or an array of such types.If E is of the form A[B] and is interpreted as a built-in array subscripting operator, S(E) is S(A) if A is of array type, S(B) if B is of array type, and empty otherwise.Otherwise, S(E) is empty. In an assignment expression of the form E1 = E2 that uses either the built-in assignment operator ([expr.ass]) or a trivial assignment operator ([class.copy.assign]), for each element X of S(E1), if modification of X would have undefined behavior under [basic.life], an object of the type of X is implicitly created in the nominated storage; no initialization is performed and the beginning of its lifetime is sequenced after the value computation of the left and right operands and before the assignment. [Note 4: This ends the lifetime of the previously-active member of the union, if any ([basic.life]). — end note] [Example 2:

union A { int x; int y[4]; };
struct B { A a; };
union C { B b; int k; };
int f() {
 C c; // does not start lifetime of any union member
 c.b.a.y[3] = 4; // OK, S(c.b.a.y[3]) contains c.b and c.b.a.y;
 // creates objects to hold union members c.b and c.b.a.y
 return c.b.a.y[3]; // OK, c.b.a.y refers to newly created object (see [basic.life])
}
struct X { const int a; int b; };
union Y { X x; int k; };
void g() {
 Y y = { { 1, 2 } }; // OK, y.x is active union member ([class.mem])
 int n = y.x.a;
 y.k = 4; // OK, ends lifetime of y.x, y.k is active member of union
 y.x.b = n; // undefined behavior: y.x.b modified outside its lifetime,
 // S(y.x.b) is empty because X's default constructor is deleted,
 // so union member y.x's lifetime does not implicitly start
}

— end example]

[Note 5: In cases where the above rule does not apply, the active member of a union can only be changed by the use of a placement new-expression. — end note] [Example 3: Consider an object u of a union type U having non-static data members m of type M and n of type N. If M has a non-trivial destructor and N has a non-trivial constructor (for instance, if they declare or inherit virtual functions), the active member of u can be safely switched from m to n using the destructor and placement new-expression as follows:

u.m.~M();
new (&u.n) N;

— end example]

A union of the form union { member-specification }; is called an anonymous union; it defines an unnamed type and an unnamed object of that type called an anonymous union member if it is a non-static data member or an anonymous union variable otherwise. Each member-declaration in the member-specification of an anonymous union shall either define one or more public non-static data members or be a static_assert-declaration. Nested types, anonymous unions, and functions shall not be declared within an anonymous union. The names of the members of an anonymous union are bound in the scope inhabited by the union declaration. [Example 1:

void f() {
 union { int a; const char* p; };
 a = 1;
 p = "Jennifer";
}

Here a and p are used like ordinary (non-member) variables, but since they are union members they have the same address. — end example]

[Note 1: A union for which objects, pointers, or references are declared is not an anonymous union. [Example 2:

void f() {
 union { int aa; char* p; } obj, *ptr = &obj;
 aa = 1; // error
 ptr->aa = 1; // OK
}

The assignment to plain aa is ill-formed since the member name is not visible outside the union, and even if it were visible, it is not associated with any particular object. — end example] — end note] [Note 2: Initialization of unions with no user-declared constructors is described in [dcl.init.aggr]. — end note]

A union-like class is a union or a class that has an anonymous union as a direct member. A union-like class X has a set of variant members. If X is a union, a non-static data member of X that is not an anonymous union is a variant member of X. In addition, a non-static data member of an anonymous union that is a member of X is also a variant member of X. At most one variant member of a union may have a default member initializer. [Example 3:

union U {
 int x = 0;
 union {
 int k;
 };
 union {
 int z;
 int y = 1; // error: initialization for second variant member of U
 };
};

— end example]

A class can be declared within a function definition; such a class is called a local class. [Note 1: A declaration in a local class cannot odr-use ([basic.def.odr]) a local entity from an enclosing scope. — end note] [Example 1:

int x;
void f() {
 static int s;
 int x;
 const int N = 5;
 extern int q();
 int arr[2];
 auto [y, z] = arr;
 struct local {
 int g() { return x; } // error: odr-use of non-odr-usable variable x
 int h() { return s; } // OK
 int k() { return ::x; } // OK
 int l() { return q(); } // OK
 int m() { return N; } // OK, not an odr-use
 int* n() { return &N; } // error: odr-use of non-odr-usable variable N
 int p() { return y; } // error: odr-use of non-odr-usable structured binding y
 };
}
local* p = 0; // error: local not found

— end example]

The base-specifier-list specifies the type of the base class subobjects contained in an object of the derived class type. [Example 1:

struct Base {
 int a, b, c;
};

struct Derived : Base {
 int b;
};

struct Derived2 : Derived {
 int c;
};

Here, an object of class Derived2 will have a subobject of class Derived which in turn will have a subobject of class Base. — end example]

A class can be derived from any number of base classes. [Note 1: The use of more than one direct base class is often called multiple inheritance. — end note] [Example 1:

class A { /* ... */ };
class B { /* ... */ };
class C { /* ... */ };
class D : public A, public B, public C { /* ... */ };

— end example]

A class shall not be specified as a direct base class of a derived class more than once. [Note 3: A class can be an indirect base class more than once and can be a direct and an indirect base class. There are limited things that can be done with such a class; lookup that finds its non-static data members and member functions in the scope of the derived class will be ambiguous. However, the static members, enumerations and types can be unambiguously referred to. — end note] [Example 2:

class X { /* ... */ };
class Y : public X, public X { /* ... */ }; // error

class L { public: int next; /* ... */ };
class A : public L { /* ... */ };
class B : public L { /* ... */ };
class C : public A, public B { void f(); /* ... */ }; // well-formed
class D : public A, public L { void f(); /* ... */ }; // well-formed

— end example]

[Note 5: In contrast, consider the case with a virtual base class:

class V { /* ... */ };
class A : virtual public V { /* ... */ };
class B : virtual public V { /* ... */ };
class C : public A, public B { /* ... */ };

virt V V A A A->V B B B->V C C C->A C->B Figure 5: Virtual base [fig:class.virt] For an object c of class type C, a single subobject of type V is shared by every base class subobject of c that has a virtual base class of type V. Given the class C defined above, an object of class C will have one subobject of class V, as shown in Figure 5. — end note]

[Note 6: A class can have both virtual and non-virtual base classes of a given type.

class B { /* ... */ };
class X : virtual public B { /* ... */ };
class Y : virtual public B { /* ... */ };
class Z : public B { /* ... */ };
class AA : public X, public Y, public Z { /* ... */ };

For an object of class AA, all virtual occurrences of base class B in the class lattice of AA correspond to a single B subobject within the object of type AA, and every other occurrence of a (non-virtual) base class B in the class lattice of AA corresponds one-to-one with a distinct B subobject within the object of type AA. Given the class AA defined above, class AA has two subobjects of class B: Z's B and the virtual B shared by X and Y, as shown in Figure 6. virtnonvirt B1 B B2 B AA AA X X AA->X Y Y AA->Y Z Z AA->Z X->B1 Y->B1 Z->B2 Figure 6: Virtual and non-virtual base [fig:class.virtnonvirt] — end note]

If a virtual member function F is declared in a class B, and, in a class D derived (directly or indirectly) from B, a declaration of a member function G corresponds ([basic.scope.scope]) to a declaration of F, ignoring trailing requires-clauses, then G overrides F. For convenience we say that any virtual function overrides itself. A virtual member function V of a class object S is a final overrider unless the most derived class ([intro.object]) of which S is a base class subobject (if any) has another member function that overrides V. In a derived class, if a virtual member function of a base class subobject has more than one final overrider the program is ill-formed. [Example 1:

struct A {
 virtual void f();
};
struct B : virtual A {
 virtual void f();
};
struct C : B , virtual A {
 using A::f;
};
void foo() {
 C c;
 c.f(); // calls B​::​f, the final overrider
 c.C::f(); // calls A​::​f because of the using-declaration
}

— end example][Example 2:

struct A { virtual void f(); };
struct B : A { };
struct C : A { void f(); };
struct D : B, C { }; // OK, A​::​f and C​::​f are the final overriders
 // for the B and C subobjects, respectively

— end example]

[Note 2: A virtual member function does not have to be visible to be overridden, for example,

struct B {
 virtual void f();
};
struct D : B {
 void f(int);
};
struct D2 : D {
 void f();
};

the function f(int) in class D hides the virtual function f() in its base class B; D:: f(int) is not a virtual function. However, f() declared in class D2 has the same name and the same parameter list as B:: f(), and therefore is a virtual function that overrides the function B:: f() even though B:: f() is not visible in class D2. — end note]

If a virtual function f in some class B is marked with the virt-specifier final and in a class D derived from B a function D:: f overrides B:: f, the program is ill-formed. [Example 3:

struct B {
 virtual void f() const final;
};
struct D : B {
 void f() const; // error: D​::​f attempts to override final B​::​f
};

— end example]

If a virtual function is marked with the virt-specifier override and does not override a member function of a base class, the program is ill-formed. [Example 4:

struct B {
 virtual void f(int);
};
struct D : B {
 virtual void f(long) override; // error: wrong signature overriding B​::​f
 virtual void f(int) override; // OK
};

— end example]

A virtual function shall not have a trailing requires-clause ([dcl.decl]). [Example 5:

template<typename T>
struct A {
 virtual void f() requires true; // error: virtual function cannot be constrained ([temp.constr.decl])
};

— end example]

If the class type in the covariant return type of D:: f differs from that of B:: f, the class type in the return type of D:: f shall be complete at the locus ([basic.scope.pdecl]) of the overriding declaration or shall be the class type D. When the overriding function is called as the final overrider of the overridden function, its result is converted to the type returned by the (statically chosen) overridden function ([expr.call]). [Example 6:

class B { };
class D : private B { friend class Derived; };
struct Base {
 virtual void vf1();
 virtual void vf2();
 virtual void vf3();
 virtual B* vf4();
 virtual B* vf5();
 void f();
};
struct No_good : public Base {
 D* vf4(); // error: B (base class of D) inaccessible
};
class A;
struct Derived : public Base {
 void vf1(); // virtual and overrides Base​::​vf1()
 void vf2(int); // not virtual, hides Base​::​vf2()
 char vf3(); // error: invalid difference in return type only
 D* vf4(); // OK, returns pointer to derived class
 A* vf5(); // error: returns pointer to incomplete class
 void f();
};
void g() {
 Derived d;
 Base* bp = &d; // standard conversion:
 // Derived* to Base*
 bp->vf1(); // calls Derived​::​vf1()
 bp->vf2(); // calls Base​::​vf2()
 bp->f(); // calls Base​::​f() (not virtual)
 B* p = bp->vf4(); // calls Derived​::​vf4() and converts the
 // result to B*
 Derived* dp = &d;
 D* q = dp->vf4(); // calls Derived​::​vf4() and does not
 // convert the result to B*
 dp->vf2(); // error: argument mismatch
}

— end example]

[Example 7: Here are some uses of virtual functions with multiple base classes:

struct A {
 virtual void f();
};
struct B1 : A { // note non-virtual derivation
 void f();
};
struct B2 : A {
 void f();
};
struct D : B1, B2 { // D has two separate A subobjects
};
void foo() {
 D d;
// A* ap = &d; // would be ill-formed: ambiguous
 B1* b1p = &d;
 A* ap = b1p;
 D* dp = &d;
 ap->f(); // calls D​::​B1​::​f
 dp->f(); // error: ambiguous
}

In class D above there are two occurrences of class A and hence two occurrences of the virtual member function A:: f. The final overrider of B1:: A:: f is B1:: f and the final overrider of B2:: A:: f is B2:: f. — end example]

[Example 8: The following example shows a function that does not have a unique final overrider:

struct A {
 virtual void f();
};
struct VB1 : virtual A { // note virtual derivation
 void f();
};
struct VB2 : virtual A {
 void f();
};
struct Error : VB1, VB2 { // error
};
struct Okay : VB1, VB2 {
 void f();
};

Both VB1:: f and VB2:: f override A:: f but there is no overrider of both of them in class Error. This example is therefore ill-formed. Class Okay is well-formed, however, because Okay:: f is a final overrider. — end example]

[Example 9: The following example uses the well-formed classes from above.

struct VB1a : virtual A { // does not declare f
};
struct Da : VB1a, VB2 {
};
void foe() {
 VB1a* vb1ap = new Da;
 vb1ap->f(); // calls VB2​::​f
}

— end example]

Explicit qualification with the scope operator ([expr.prim.id.qual]) suppresses the virtual call mechanism. [Example 10:

class B { public: virtual void f(); };
class D : public B { public: void f(); };
void D::f() { /* ... */ B::f(); }

Here, the function call in D:: f really does call B:: f and not D:: f. — end example]

A virtual function is specified as a pure virtual function by using a pure-specifier ([class.mem]) in the function declaration in the class definition. [Note 2: Such a function might be inherited: see below. — end note] A class is an abstract class if it has at least one pure virtual function. [Note 3: An abstract class can be used only as a base class of some other class; no objects of an abstract class can be created except as subobjects of a class derived from it ([basic.def], [class.mem]). — end note] A pure virtual function need be defined only if called with, or as if with ([class.dtor]), the qualified-id syntax ([expr.prim.id.qual]). [Example 1:

class point { /* ... */ };
class shape { // abstract class
 point center;
public:
 point where() { return center; }
 void move(point p) { center=p; draw(); }
 virtual void rotate(int) = 0; // pure virtual
 virtual void draw() = 0; // pure virtual
};

— end example] [Note 4: A function declaration cannot provide both a pure-specifier and a definition. — end note] [Example 2:

struct C {
 virtual void f() = 0 { }; // error
};

— end example]

A class is abstract if it has at least one pure virtual function for which the final overrider is pure virtual. [Example 3:

class ab_circle : public shape {
 int radius;
public:
 void rotate(int) { }
 // ab_circle​::​draw() is a pure virtual
};

Since shape:: draw() is a pure virtual function ab_circle:: draw() is a pure virtual by default. The alternative declaration,

class circle : public shape {
 int radius;
public:
 void rotate(int) { }
 void draw(); // a definition is required somewhere
};

would make class circle non-abstract and a definition of circle:: draw() must be provided. — end example]

Members of a class defined with the keyword class are private by default. Members of a class defined with the keywords struct or union are public by default. [Example 1:

class X {
 int a; // X​::​a is private by default
};
struct S {
 int a; // S​::​a is public by default
};

— end example]

Access control is applied uniformly to declarations and expressions. [Note 2: Access control applies to members nominated by friend declarations ([class.friend]) and using-declarations ([namespace.udecl]). — end note] When a using-declarator is named, access control is applied to it, not to the declarations that replace it. For an overload set, access control is applied only to the function selected by overload resolution. [Example 2:

struct S {
 void f(int);
private:
 void f(double);
};
void g(S* sp) {
 sp->f(2); // OK, access control applied after overload resolution
}

— end example] [Note 3: Because access control applies to the declarations named, if access control is applied to a typedef-name, only the accessibility of the typedef or alias declaration itself is considered. The accessibility of the entity referred to by the typedef-name is not considered. For example,

class A {
 class B { };
public:
 typedef B BB;
};
void f() {
 A::BB x; // OK, typedef A​::​BB is public
 A::B y; // access error, A​::​B is private
}

— end note]

[Example 3:

class A {
 typedef int I; // private member
 I f();
 friend I g(I);
 static I x;
 template<int> struct Q;
 template<int> friend struct R;
protected:
 struct B { };
};
A::I A::f() { return 0; }
A::I g(A::I p = A::x);
A::I g(A::I p) { return 0; }
A::I A::x = 0;
template<A::I> struct A::Q { };
template<A::I> struct R { };
struct D: A::B, A { };

Here, all the uses of A:: I are well-formed because A:: f, A:: x, and A:: Q are members of class A and g and R are friends of class A. This implies, for example, that access checking on the first use of A:: I must be deferred until it is determined that this use of A:: I is as the return type of a member of class A. Similarly, the use of A:: B as a base-specifier is well-formed because D is derived from A, so checking of base-specifiers must be deferred until the entire base-specifier-list has been seen. — end example]

Access for a default template-argument ([temp.param]) is checked in the context in which it appears rather than at any points of use of it. [Example 4:

class B { };
template <class T> class C {
protected:
 typedef T TT;
};
template <class U, class V = typename U::TT>
class D : public U { };
D <C<B> >* d; // access error, C​::​TT is protected

— end example]

Member declarations can be labeled by an access-specifier ([class.derived]): access-specifier: member-specificationopt An access-specifier specifies the access rules for members following it until the end of the class or until another access-specifier is encountered. [Example 1:

class X {
 int a; // X​::​a is private by default: class used
public:
 int b; // X​::​b is public
 int c; // X​::​c is public
};

— end example]

Any number of access specifiers is allowed and no particular order is required. [Example 2:

struct S {
 int a; // S​::​a is public by default: struct used
protected:
 int b; // S​::​b is protected
private:
 int c; // S​::​c is private
public:
 int d; // S​::​d is public
};

— end example]

When a member is redeclared within its class definition, the access specified at its redeclaration shall be the same as at its initial declaration. [Example 3:

struct S {
 class A;
 enum E : int;
private:
 class A { }; // error: cannot change access
 enum E: int { e0 }; // error: cannot change access
};

— end example]

[Note 1: In a derived class, the lookup of a base class name will find the injected-class-name instead of the name of the base class in the scope in which it was declared. The injected-class-name might be less accessible than the name of the base class in the scope in which it was declared. — end note][Example 4:

class A { };
class B : private A { };
class C : public B {
 A* p; // error: injected-class-name A is inaccessible
 ::A* q; // OK
};

— end example]

In the absence of an access-specifier for a base class, public is assumed when the derived class is defined with the class-key struct and private is assumed when the class is defined with the class-key class. [Example 1:

class B { /* ... */ };
class D1 : private B { /* ... */ };
class D2 : public B { /* ... */ };
class D3 : B { /* ... */ }; // B private by default
struct D4 : public B { /* ... */ };
struct D5 : private B { /* ... */ };
struct D6 : B { /* ... */ }; // B public by default
class D7 : protected B { /* ... */ };
struct D8 : protected B { /* ... */ };

Here B is a public base of D2, D4, and D6, a private base of D1, D3, and D5, and a protected base of D7 and D8. — end example]

[Note 1: A member of a private base class can be inaccessible as inherited, but accessible directly. Because of the rules on pointer conversions ([conv.ptr]) and explicit casts ([expr.type.conv], [expr.static.cast], [expr.cast]), a conversion from a pointer to a derived class to a pointer to an inaccessible base class can be ill-formed if an implicit conversion is used, but well-formed if an explicit cast is used. For example,

class B {
public:
 int mi; // non-static member
 static int si; // static member
};
class D : private B {
};
class DD : public D {
 void f();
};
void DD::f() {
 mi = 3; // error: mi is private in D
 si = 3; // error: si is private in D
 ::B b;
 b.mi = 3; // OK (b.mi is different from this->mi)
 b.si = 3; // OK (b.si is different from this->si)
 ::B::si = 3; // OK
 ::B* bp1 = this; // error: B is a private base class
 ::B* bp2 = (::B*)this; // OK with cast
 bp2->mi = 3; // OK, access through a pointer to B.
}

— end note]

A base class B of N is accessible at R, if an invented public member of B would be a public member of N, orR occurs in a direct member or friend of class N, and an invented public member of B would be a private or protected member of N, orR occurs in a direct member or friend of a class P derived from N, and an invented public member of B would be a private or protected member of P, orthere exists a class S such that B is a base class of S accessible at R and S is a base class of N accessible at R.[Example 2:

class B {
public:
 int m;
};
class S: private B {
 friend class N;
};
class N: private S {
 void f() {
 B* p = this; // OK because class S satisfies the fourth condition above: B is a base class of N
 // accessible in f() because B is an accessible base class of S and S is an accessible
 // base class of N.
 }
};

— end example]

If a base class is accessible, one can implicitly convert a pointer to a derived class to a pointer to that base class ([conv.ptr], [conv.mem]). [Note 2: It follows that members and friends of a class X can implicitly convert an X* to a pointer to a private or protected immediate base class of X. — end note] The access to a member is affected by the class in which the member is named. This naming class is the class in whose scope name lookup performed a search that found the member. [Note 3: This class can be explicit, e.g., when a qualified-id is used, or implicit, e.g., when a class member access operator ([expr.ref]) is used (including cases where an implicit “this->” is added). If both a class member access operator and a qualified-id are used to name the member (as in p->T:: m), the class naming the member is the class denoted by the nested-name-specifier of the qualified-id (that is, T). — end note] A member m is accessible at the point R when named in class N if m as a member of N is public, orm as a member of N is private, and R occurs in a direct member or friend of class N, orm as a member of N is protected, and R occurs in a direct member or friend of class N, or in a member of a class P derived from N, where m as a member of P is public, private, or protected, orthere exists a base class B of N that is accessible at R, and m is accessible at R when named in class B. [Example 3:

class B;
class A {
private:
 int i;
 friend void f(B*);
};
class B : public A { };
void f(B* p) {
 p->i = 1; // OK, B* can be implicitly converted to A*, and f has access to i in A
}

— end example]

A friend of a class is a function or class that is given permission to name the private and protected members of the class. A class specifies its friends, if any, by way of friend declarations. Such declarations give special access rights to the friends, but they do not make the nominated friends members of the befriending class. [Example 1: The following example illustrates the differences between members and friends:

class X {
 int a;
 friend void friend_set(X*, int);
public:
 void member_set(int);
};
void friend_set(X* p, int i) { p->a = i; }
void X::member_set(int i) { a = i; }
void f() {
 X obj;
 friend_set(&obj,10);
 obj.member_set(10);
}

— end example]

Declaring a class to be a friend implies that private and protected members of the class granting friendship can be named in the base-specifiers and member declarations of the befriended class. [Example 2:

class A {
 class B { };
 friend class X;
};
struct X : A::B { // OK, A​::​B accessible to friend
 A::B mx; // OK, A​::​B accessible to member of friend
 class Y {
 A::B my; // OK, A​::​B accessible to nested member of friend
 };
};

— end example] [Example 3:

class X {
 enum { a=100 };
 friend class Y;
};
class Y {
 int v[X::a]; // OK, Y is a friend of X
};
class Z {
 int v[X::a]; // error: X​::​a is private
};

— end example]

A friend declaration that does not declare a function shall have one of the following forms: friend elaborated-type-specifier;friend simple-type-specifier;friend typename-specifier; [Note 1: A friend declaration can be the declaration in a template-declaration ([temp.pre], [temp.friend]). — end note] If the type specifier in a friend declaration designates a (possibly cv-qualified) class type, that class is declared as a friend; otherwise, the friend declaration is ignored. [Example 4:

class C;
typedef C Ct;
class X1 {
 friend C; // OK, class C is a friend
};
class X2 {
 friend Ct; // OK, class C is a friend
 friend D; // error: D not found
 friend class D; // OK, elaborated-type-specifier declares new class
};
template <typename T> class R {
 friend T;
};
R<C> rc; // class C is a friend of R<C>
R<int> Ri; // OK, "friend int;" is ignored

— end example]

[Note 2: A friend declaration refers to an entity, not (all overloads of) a name. A member function of a class X can be a friend of a class Y. [Example 5:

class Y {
 friend char* X::foo(int);
 friend X::X(char); // constructors can be friends
 friend X::~X(); // destructors can be friends
};

— end example] — end note]

A function may be defined in a friend declaration of a class if and only if the class is a non-local class ([class.local]) and the function name is unqualified. [Example 6:

class M {
 friend void f() { } // definition of global f, a friend of M,
 // not the definition of a member function
};

— end example]

Friendship is neither inherited nor transitive. [Example 7:

class A {
 friend class B;
 int a;
};
class B {
 friend class C;
};
class C {
 void f(A* p) {
 p->a++; // error: C is not a friend of A despite being a friend of a friend
 }
};
class D : public B {
 void f(A* p) {
 p->a++; // error: D is not a friend of A despite being derived from a friend
 }
};

— end example]

[Note 4: A friend declaration never binds any names ([dcl.meaning], [dcl.type.elab]). — end note] [Example 8:

// Assume f and g have not yet been declared.
void h(int);
template <class T> void f2(T);
namespace A {
 class X {
 friend void f(X); // A​::​f(X) is a friend
 class Y {
 friend void g(); // A​::​g is a friend
 friend void h(int); // A​::​h is a friend
 // ​::​h not considered
 friend void f2<>(int); // ​::​f2<>(int) is a friend
 };
 };
 // A​::​f, A​::​g and A​::​h are not visible here
 X x;
 void g() { f(x); } // definition of A​::​g
 void f(X) { /* ... */ } // definition of A​::​f
 void h(int) { /* ... */ } // definition of A​::​h
 // A​::​f, A​::​g and A​::​h are visible here and known to be friends
}
using A::x;
void h() {
 A::f(x);
 A::X::f(x); // error: f is not a member of A​::​X
 A::X::Y::g(); // error: g is not a member of A​::​X​::​Y
}

— end example] [Example 9:

class X;
void a();
void f() {
 class Y;
 extern void b();
 class A {
 friend class X; // OK, but X is a local class, not ​::​X
 friend class Y; // OK
 friend class Z; // OK, introduces local class Z
 friend void a(); // error, ​::​a is not considered
 friend void b(); // OK
 friend void c(); // error
 };
 X* px; // OK, but ​::​X is found
 Z* pz; // error: no Z is found
}

— end example]

An additional access check beyond those described earlier in [class.access] is applied when a non-static data member or non-static member function is a protected member of its naming class ([class.access.base]). As described earlier, access to a protected member is granted because the reference occurs in a friend or direct member of some class C. If the access is to form a pointer to member ([expr.unary.op]), the nested-name-specifier shall denote C or a class derived from C. All other accesses involve a (possibly implicit) object expression ([expr.ref]). In this case, the class of the object expression shall be C or a class derived from C. [Example 1:

class B {
protected:
 int i;
 static int j;
};
class D1 : public B {
};
class D2 : public B {
 friend void fr(B*,D1*,D2*);
 void mem(B*,D1*);
};
void fr(B* pb, D1* p1, D2* p2) {
 pb->i = 1; // error
 p1->i = 2; // error
 p2->i = 3; // OK (access through a D2)
 p2->B::i = 4; // OK (access through a D2, even though naming class is B)
 int B::* pmi_B = &B::i; // error
 int B::* pmi_B2 = &D2::i; // OK (type of &D2​::​i is int B​::​*)
 B::j = 5; // error: not a friend of naming class B
 D2::j = 6; // OK (because refers to static member)
}
void D2::mem(B* pb, D1* p1) {
 pb->i = 1; // error
 p1->i = 2; // error
 i = 3; // OK (access through this)
 B::i = 4; // OK (access through this, qualification ignored)
 int B::* pmi_B = &B::i; // error
 int B::* pmi_B2 = &D2::i; // OK
 j = 5; // OK (because j refers to static member)
 B::j = 6; // OK (because B​::​j refers to static member)
}
void g(B* pb, D1* p1, D2* p2) {
 pb->i = 1; // error
 p1->i = 2; // error
 p2->i = 3; // error
}

— end example]

The access rules ([class.access]) for a virtual function are determined by its declaration and are not affected by the rules for a function that later overrides it. [Example 1:

class B {
public:
 virtual int f();
};
class D : public B {
private:
 int f();
};
void f() {
 D d;
 B* pb = &d;
 D* pd = &d;
 pb->f(); // OK, B​::​f() is public, D​::​f() is invoked
 pd->f(); // error: D​::​f() is private
}

— end example]

Access is checked at the call point using the type of the expression used to denote the object for which the member function is called (B* in the example above). The access of the member function in the class in which it was defined (D in the example above) is in general not known.

If a declaration can be reached by several paths through a multiple inheritance graph, the access is that of the path that gives most access. [Example 1:

class W { public: void f(); };
class A : private virtual W { };
class B : public virtual W { };
class C : public A, public B {
 void f() { W::f(); } // OK
};

Since W:: f() is available to C:: f() along the public path through B, access is allowed. — end example]

A nested class is a member and as such has the same access rights as any other member. The members of an enclosing class have no special access to members of a nested class; the usual access rules ([class.access]) shall be obeyed. [Example 1:

class E {
 int x;
 class B { };
 class I {
 B b; // OK, E​::​I can access E​::​B
 int y;
 void f(E* p, int i) {
 p->x = i; // OK, E​::​I can access E​::​x
 }
 };
 int g(I* p) {
 return p->y; // error: I​::​y is private
 }
};

— end example]

An object of class type can be initialized with a parenthesized expression-list, where the expression-list is construed as an argument list for a constructor that is called to initialize the object. Alternatively, a single assignment-expression can be specified as an initializer using the = form of initialization. Either direct-initialization semantics or copy-initialization semantics apply; see [dcl.init]. [Example 1:

struct complex {
 complex();
 complex(double);
 complex(double,double);
};
complex sqrt(complex,complex);
complex a(1); // initialized by calling complex(double) with argument 1
complex b = a; // initialized as a copy of a
complex c = complex(1,2); // initialized by calling complex(double,double) with arguments 1 and 2
complex d = sqrt(b,c); // initialized by calling sqrt(complex,complex) with d as its result object
complex e; // initialized by calling complex()
complex f = 3; // initialized by calling complex(double) with argument 3
complex g = { 1, 2 }; // initialized by calling complex(double, double) with arguments 1 and 2

— end example] [Note 1: Overloading of the assignment operator ([over.ass]) has no effect on initialization. — end note]

An object of class type can also be initialized by a braced-init-list. List-initialization semantics apply; see [dcl.init] and [dcl.init.list]. [Example 2:

complex v[6] = { 1, complex(1,2), complex(), 2 };

Here, complex:: complex(double) is called for the initialization of v[0] and v[3], complex:: complex(double, double) is called for the initialization of v[1], complex:: complex() is called for the initialization of v[2], v[4], and v[5]. For another example,

struct X {
 int i;
 float f;
 complex c;
} x = { 99, 88.8, 77.7 };

Here, x.i is initialized with 99, x.f is initialized with 88.8, and complex:: complex(double) is called for the initialization of x.c. — end example] [Note 2: Braces can be elided in the initializer-list for any aggregate, even if the aggregate has members of a class type with user-defined type conversions; see [dcl.init.aggr]. — end note]

A mem-initializer-list can initialize a base class using any class-or-decltype that denotes that base class type. [Example 1:

struct A { A(); };
typedef A global_A;
struct B { };
struct C: public A, public B { C(); };
C::C(): global_A() { } // mem-initializer for base A

— end example]

If a mem-initializer-id is ambiguous because it designates both a direct non-virtual base class and an indirect virtual base class, the mem-initializer is ill-formed. [Example 2:

struct A { A(); };
struct B: public virtual A { };
struct C: public A, public B { C(); };
C::C(): A() { } // error: which A?

— end example]

A mem-initializer-list can delegate to another constructor of the constructor's class using any class-or-decltype that denotes the constructor's class itself. If a mem-initializer-id designates the constructor's class, it shall be the only mem-initializer; the constructor is a delegating constructor, and the constructor selected by the mem-initializer is the target constructor. The target constructor is selected by overload resolution. Once the target constructor returns, the body of the delegating constructor is executed. If a constructor delegates to itself directly or indirectly, the program is ill-formed, no diagnostic required. [Example 3:

struct C {
 C( int ) { } // #1: non-delegating constructor
 C(): C(42) { } // #2: delegates to #1
 C( char c ) : C(42.0) { } // #3: ill-formed due to recursion with #4
 C( double d ) : C('a') { } // #4: ill-formed due to recursion with #3
};

— end example]

The expression-list or braced-init-list in a mem-initializer is used to initialize the designated subobject (or, in the case of a delegating constructor, the complete class object) according to the initialization rules of [dcl.init] for direct-initialization. [Example 4:

struct B1 { B1(int); /* ... */ };
struct B2 { B2(int); /* ... */ };
struct D : B1, B2 {
 D(int);
 B1 b;
 const int c;
};
D::D(int a) : B2(a+1), B1(a+2), c(a+3), b(a+4) { /* ... */ }
D d(10);

— end example] [Note 2: The initialization performed by each mem-initializer constitutes a full-expression ([intro.execution]). Any expression in a mem-initializer is evaluated as part of the full-expression that performs the initialization. — end note] A mem-initializer where the mem-initializer-id denotes a virtual base class is ignored during execution of a constructor of any class that is not the most derived class.

A temporary expression bound to a reference member in a mem-initializer is ill-formed. [Example 5:

struct A {
 A() : v(42) { } // error
 const int& v;
};

— end example]

In a non-delegating constructor other than an implicitly-defined copy/move constructor ([class.copy.ctor]), if a given potentially constructed subobject is not designated by a mem-initializer-id (including the case where there is no mem-initializer-list because the constructor has no ctor-initializer), then if the entity is a non-static data member that has a default member initializer ([class.mem]) and either the constructor's class is a union ([class.union]), and no other variant member of that union is designated by a mem-initializer-id orthe constructor's class is not a union, and, if the entity is a member of an anonymous union, no other member of that union is designated by a mem-initializer-id, the entity is initialized from its default member initializer as specified in [dcl.init];otherwise, if the entity is an anonymous union or a variant member ([class.union.anon]), no initialization is performed;otherwise, the entity is default-initialized ([dcl.init]).[Note 3: An abstract class ([class.abstract]) is never a most derived class, thus its constructors never initialize virtual base classes, therefore the corresponding mem-initializers can be omitted. — end note] An attempt to initialize more than one non-static data member of a union renders the program ill-formed. [Note 4: After the call to a constructor for class X for an object with automatic or dynamic storage duration has completed, if the constructor was not invoked as part of value-initialization and a member of X is neither initialized nor given a value during execution of the compound-statement of the body of the constructor, the member has an indeterminate value. — end note] [Example 6:

struct A {
 A();
};
struct B {
 B(int);
};
struct C {
 C() { } // initializes members as follows:
 A a; // OK, calls A​::​A()
 const B b; // error: B has no default constructor
 int i; // OK, i has indeterminate value
 int j = 5; // OK, j has the value 5
};

— end example]

If a given non-static data member has both a default member initializer and a mem-initializer, the initialization specified by the mem-initializer is performed, and the non-static data member's default member initializer is ignored. [Example 7: Given

struct A {
 int i = /* some integer expression with side effects */ ;
 A(int arg) : i(arg) { }
 // ...
};

the A(int) constructor will simply initialize i to the value of arg, and the side effects in i's default member initializer will not take place. — end example]

A temporary expression bound to a reference member from a default member initializer is ill-formed. [Example 8:

struct A {
 A() = default; // OK
 A(int v) : v(v) { } // OK
 const int& v = 42; // OK
};
A a1; // error: ill-formed binding of temporary to reference
A a2(1); // OK, unfortunately

— end example]

[Example 9:

struct V {
 V();
 V(int);
};
struct A : virtual V {
 A();
 A(int);
};
struct B : virtual V {
 B();
 B(int);
};
struct C : A, B, virtual V {
 C();
 C(int);
};
A::A(int i) : V(i) { /* ... */ }
B::B(int i) { /* ... */ }
C::C(int i) { /* ... */ }
V v(1); // use V(int)
A a(2); // use V(int)
B b(3); // use V()
C c(4); // use V()

— end example]

[Note 7: The expression-list or braced-init-list of a mem-initializer is in the function parameter scope of the constructor and can use this to refer to the object being initialized. — end note] [Example 10:

class X {
 int a;
 int b;
 int i;
 int j;
public:
 const int& r;
 X(int i): r(a), b(i), i(i), j(this->i) { }
};

initializes X:: r to refer to X:: a, initializes X:: b with the value of the constructor parameter i, initializes X:: i with the value of the constructor parameter i, and initializes X:: j with the value of X:: i; this takes place each time an object of class X is created. — end example]

Member functions (including virtual member functions, [class.virtual]) can be called for an object under construction. Similarly, an object under construction can be the operand of the typeid operator ([expr.typeid]) or of a dynamic_cast ([expr.dynamic.cast]). However, if these operations are performed in a ctor-initializer (or in a function called directly or indirectly from a ctor-initializer) before all the mem-initializers for base classes have completed, the program has undefined behavior. [Example 11:

class A {
public:
 A(int);
};
class B : public A {
 int j;
public:
 int f();
 B() : A(f()), // undefined behavior: calls member function but base A not yet initialized
 j(f()) { } // well-defined: bases are all initialized
};
class C {
public:
 C(int);
};
class D : public B, C {
 int i;
public:
 D() : C(f()), // undefined behavior: calls member function but base C not yet initialized
 i(f()) { } // well-defined: bases are all initialized
};

— end example]

A mem-initializer followed by an ellipsis is a pack expansion ([temp.variadic]) that initializes the base classes specified by a pack expansion in the base-specifier-list for the class. [Example 12:

template<class... Mixins>
class X : public Mixins... {
public:
 X(const Mixins&... mixins) : Mixins(mixins)... { }
};

— end example]

When a constructor for type B is invoked to initialize an object of a different type D (that is, when the constructor was inherited ([namespace.udecl])), initialization proceeds as if a defaulted default constructor were used to initialize the D object and each base class subobject from which the constructor was inherited, except that the B subobject is initialized by the invocation of the inherited constructor. The complete initialization is considered to be a single function call; in particular, the initialization of the inherited constructor's parameters is sequenced before the initialization of any part of the D object. [Example 1:

struct B1 {
 B1(int, ...) { }
};
struct B2 {
 B2(double) { }
};
int get();
struct D1 : B1 {
 using B1::B1; // inherits B1(int, ...)
 int x;
 int y = get();
};
void test() {
 D1 d(2, 3, 4); // OK, B1 is initialized by calling B1(2, 3, 4),
 // then d.x is default-initialized (no initialization is performed),
 // then d.y is initialized by calling get()
 D1 e; // error: D1 has no default constructor
}
struct D2 : B2 {
 using B2::B2;
 B1 b;
};
D2 f(1.0); // error: B1 has no default constructor
struct W { W(int); };
struct X : virtual W { using W::W; X() = delete; };
struct Y : X { using X::X; };
struct Z : Y, virtual W { using Y::Y; };
Z z(0); // OK, initialization of Y does not invoke default constructor of X
template<class T> struct Log : T {
 using T::T; // inherits all constructors from class T
 ~Log() { std::clog << "Destroying wrapper" << std::endl; }
};

Class template Log wraps any class and forwards all of its constructors, while writing a message to the standard log whenever an object of class Log is destroyed. — end example]

If the constructor was inherited from multiple base class subobjects of type B, the program is ill-formed. [Example 2:

struct A { A(int); };
struct B : A { using A::A; };
struct C1 : B { using B::B; };
struct C2 : B { using B::B; };
struct D1 : C1, C2 {
 using C1::C1;
 using C2::C2;
};
struct V1 : virtual B { using B::B; };
struct V2 : virtual B { using B::B; };
struct D2 : V1, V2 {
 using V1::V1;
 using V2::V2;
};
D1 d1(0); // error: ambiguous
D2 d2(0); // OK, initializes virtual B base class, which initializes the A base class
 // then initializes the V1 and V2 base classes as if by a defaulted default constructor
struct M { M(); M(int); };
struct N : M { using M::M; };
struct O : M {};
struct P : N, O { using N::N; using O::O; };
P p(0); // OK, use M(0) to initialize N's base class,
 // use M() to initialize O's base class

— end example]

When an object is initialized by an inherited constructor, initialization of the object is complete when the initialization of all subobjects is complete.

For an object with a non-trivial constructor, referring to any non-static member or base class of the object before the constructor begins execution results in undefined behavior. For an object with a non-trivial destructor, referring to any non-static member or base class of the object after the destructor finishes execution results in undefined behavior. [Example 1:

struct X { int i; };
struct Y : X { Y(); }; // non-trivial
struct A { int a; };
struct B : public A { int j; Y y; }; // non-trivial
extern B bobj;
B* pb = &bobj; // OK
int* p1 = &bobj.a; // undefined behavior: refers to base class member
int* p2 = &bobj.y.i; // undefined behavior: refers to member's member
A* pa = &bobj; // undefined behavior: upcast to a base class type
B bobj; // definition of bobj
extern X xobj;
int* p3 = &xobj.i; // OK, X is a trivial class
X xobj;

For another example,

struct W { int j; };
struct X : public virtual W { };
struct Y {
 int* p;
 X x;
 Y() : p(&x.j) { // undefined, x is not yet constructed
 }
};

— end example]

During the construction of an object, if the value of the object or any of its subobjects is accessed through a glvalue that is not obtained, directly or indirectly, from the constructor's this pointer, the value of the object or subobject thus obtained is unspecified. [Example 2:

struct C;
void no_opt(C*);
struct C {
 int c;
 C() : c(0) { no_opt(this); }
};
const C cobj;
void no_opt(C* cptr) {
 int i = cobj.c * 100; // value of cobj.c is unspecified
 cptr->c = 1;
 cout << cobj.c * 100 // value of cobj.c is unspecified
 << '\n';
}
extern struct D d;
struct D {
 D(int a) : a(a), b(d.a) {}
 int a, b;
};
D d = D(1); // value of d.b is unspecified

— end example]

To explicitly or implicitly convert a pointer (a glvalue) referring to an object of class X to a pointer (reference) to a direct or indirect base class B of X, the construction of X and the construction of all of its direct or indirect bases that directly or indirectly derive from B shall have started and the destruction of these classes shall not have completed, otherwise the conversion results in undefined behavior. To form a pointer to (or access the value of) a direct non-static member of an object obj, the construction of obj shall have started and its destruction shall not have completed, otherwise the computation of the pointer value (or accessing the member value) results in undefined behavior. [Example 3:

struct A { };
struct B : virtual A { };
struct C : B { };
struct D : virtual A { D(A*); };
struct X { X(A*); };
struct E : C, D, X {
 E() : D(this), // undefined behavior: upcast from E* to A* might use path E* → D* → A*
 // but D is not constructed
 // “D((C*)this)'' would be defined: E* → C* is defined because E() has started,
 // and C* → A* is defined because C is fully constructed
 X(this) {} // defined: upon construction of X, C/B/D/A sublattice is fully constructed
};

— end example]

Member functions, including virtual functions ([class.virtual]), can be called during construction or destruction ([class.base.init]). When a virtual function is called directly or indirectly from a constructor or from a destructor, including during the construction or destruction of the class's non-static data members, and the object to which the call applies is the object (call it x) under construction or destruction, the function called is the final overrider in the constructor's or destructor's class and not one overriding it in a more-derived class. If the virtual function call uses an explicit class member access ([expr.ref]) and the object expression refers to the complete object of x or one of that object's base class subobjects but not x or one of its base class subobjects, the behavior is undefined. [Example 4:

struct V {
 virtual void f();
 virtual void g();
};
struct A : virtual V {
 virtual void f();
};
struct B : virtual V {
 virtual void g();
 B(V*, A*);
};
struct D : A, B {
 virtual void f();
 virtual void g();
 D() : B((A*)this, this) { }
};
B::B(V* v, A* a) {
 f(); // calls V​::​f, not A​::​f
 g(); // calls B​::​g, not D​::​g
 v->g(); // v is base of B, the call is well-defined, calls B​::​g
 a->f(); // undefined behavior: a's type not a base of B
}

— end example]

dynamic_casts ([expr.dynamic.cast]) can be used during construction or destruction ([class.base.init]). When a dynamic_cast is used in a constructor (including the mem-initializer or default member initializer for a non-static data member) or in a destructor, or used in a function called (directly or indirectly) from a constructor or destructor, if the operand of the dynamic_cast refers to the object under construction or destruction, this object is considered to be a most derived object that has the type of the constructor or destructor's class. If the operand of the dynamic_cast refers to the object under construction or destruction and the static type of the operand is not a pointer to or object of the constructor or destructor's own class or one of its bases, the dynamic_cast results in undefined behavior. [Example 5:

struct V {
 virtual void f();
};
struct A : virtual V { };
struct B : virtual V {
 B(V*, A*);
};
struct D : A, B {
 D() : B((A*)this, this) { }
};
B::B(V* v, A* a) {
 typeid(*this); // type_info for B
 typeid(*v); // well-defined: *v has type V, a base of B yields type_info for B
 typeid(*a); // undefined behavior: type A not a base of B
 dynamic_cast<B*>(v); // well-defined: v of type V*, V base of B results in B*
 dynamic_cast<B*>(a); // undefined behavior: a has type A*, A not a base of B
}

— end example]

[Example 1:

class Thing {
public:
 Thing();
 ~Thing();
 Thing(const Thing&);
};
Thing f() {
 Thing t;
 return t;
}
Thing t2 = f();
struct A {
 void *p;
 constexpr A(): p(this) {}
};
constexpr A g() {
 A loc;
 return loc;
}
constexpr A a; // well-formed, a.p points to a
constexpr A b = g(); // error: b.p would be dangling ([expr.const])
void h() {
 A c = g(); // well-formed, c.p can point to c or be dangling
}

Here the criteria for elision can eliminate the copying of the object t with automatic storage duration into the result object for the function call f(), which is the non-local object t2. Effectively, the construction of t can be viewed as directly initializing t2, and that object's destruction will occur at program exit. Adding a move constructor to Thing has the same effect, but it is the move construction from the object with automatic storage duration to t2 that is elided. — end example]

[Example 2:

class Thing {
public:
 Thing();
 ~Thing();
 Thing(Thing&&);
private:
 Thing(const Thing&);
};
Thing f(bool b) {
 Thing t;
 if (b)
 throw t; // OK, Thing(Thing&&) used (or elided) to throw t
 return t; // OK, Thing(Thing&&) used (or elided) to return t
}
Thing t2 = f(false); // OK, no extra copy/move performed, t2 constructed by call to f
struct Weird {
 Weird();
 Weird(Weird&);
};
Weird g(bool b) {
 static Weird w1;
 Weird w2;
 if (b)
 return w1; // OK, uses Weird(Weird&)
 else
 return w2; // error: w2 in this context is an xvalue
}
int& h(bool b, int i) {
 static int s;
 if (b)
 return s; // OK
 else
 return i; // error: i is an xvalue
}
decltype(auto) h2(Thing t) {
 return t; // OK, t is an xvalue and h2's return type is Thing
}
decltype(auto) h3(Thing t) {
 return (t); // OK, (t) is an xvalue and h3's return type is Thing&&
}

— end example]

[Example 3:

template<class T> void g(const T&);
template<class T> void f() {
 T x;
 try {
 T y;
 try { g(x); }
 catch (...) {
 if (/*...*/)
 throw x; // does not move
 throw y; // moves
 }
 g(y);
 } catch(...) {
 g(x);
 g(y); // error: y is not in scope
 }
}

— end example]

If the member-specification does not explicitly declare any member or friend named operator==, an == operator function is declared implicitly for each three-way comparison operator function defined as defaulted in the member-specification, with the same access and function-definition and in the same class scope as the respective three-way comparison operator function, except that the return type is replaced with bool and the declarator-id is replaced with operator==. [Note 1: Such an implicitly-declared == operator for a class X is defined as defaulted in the definition of X and has the same parameter-declaration-clause and trailing requires-clause as the respective three-way comparison operator. It is declared with friend, virtual, constexpr, or consteval if the three-way comparison operator function is so declared. If the three-way comparison operator function has no noexcept-specifier, the implicitly-declared == operator function has an implicit exception specification ([except.spec]) that can differ from the implicit exception specification of the three-way comparison operator function. — end note] [Example 1:

template<typename T> struct X {
 friend constexpr std::partial_ordering operator<=>(X, X) requires (sizeof(T) != 1) = default;
 // implicitly declares: friend constexpr bool operator==(X, X) requires (sizeof(T) != 1) = default;
 [[nodiscard]] virtual std::strong_ordering operator<=>(const X&) const = default;
 // implicitly declares: [[nodiscard]] virtual bool operator==(const X&) const = default;
};

— end example] [Note 2: The == operator function is declared implicitly even if the defaulted three-way comparison operator function is defined as deleted. — end note]

[Example 1:

struct D {
 int i;
 friend bool operator==(const D& x, const D& y) = default;
 // OK, returns x.i == y.i
};

— end example]

A secondary comparison operator is a relational operator ([expr.rel]) or the != operator. A defaulted operator function ([over.binary]) for a secondary comparison operator @ shall have a declared return type bool.

The operator function with parameters x and y is defined as deleted if overload resolution ([over.match]), as applied to x @ y, does not result in a usable candidate, orthe candidate selected by overload resolution is not a rewritten candidate.Otherwise, the operator function yields x @ y. The defaulted operator function is not considered as a candidate in the overload resolution for the @ operator.

[Example 1:

struct HasNoLessThan { };
struct C {
 friend HasNoLessThan operator<=>(const C&, const C&);
 bool operator<(const C&) const = default; // OK, function is deleted
};

— end example]

[Note 1: Each of two or more entities with the same name in the same scope, which must be functions or function templates, is commonly called an “overload”. — end note]

When a function is named in a call, which function declaration is being referenced and the validity of the call are determined by comparing the types of the arguments at the point of use with the types of the parameters in the declarations in the overload set. This function selection process is called overload resolution and is defined in [over.match]. [Example 1:

double abs(double);
int abs(int);
abs(1); // calls abs(int);
abs(1.0); // calls abs(double);

— end example]

Because other than in list-initialization only one user-defined conversion is allowed in an implicit conversion sequence, special rules apply when selecting the best user-defined conversion ([over.match.best], [over.best.ics]). [Example 2:

class T {
public:
 T();
};
class C : T {
public:
 C(int);
};
T a = 1; // error: no viable conversion (T(C(1)) not considered)

— end example]

A defaulted move special member function ([class.copy.ctor], [class.copy.assign]) that is defined as deleted is excluded from the set of candidate functions in all contexts. A constructor inherited from class type C ([class.inhctor.init]) that has a first parameter of type “reference to cv1 P” (including such a constructor instantiated from a template) is excluded from the set of candidate functions when constructing an object of type cv2 D if the argument list has exactly one argument and C is reference-related to P and P is reference-related to D. [Example 3:

struct A {
 A(); // #1
 A(A &&); // #2
 template<typename T> A(T &&); // #3
};
struct B : A {
 using A::A;
 B(const B &); // #4
 B(B &&) = default; // #5, implicitly deleted
 struct X { X(X &&) = delete; } x;
};
extern B b1;
B b2 = static_cast<B&&>(b1); // calls #4: #1 is not viable, #2, #3, and #5 are not candidates
struct C { operator B&&(); };
B b3 = C(); // calls #4

— end example]

Of interest in [over.call.func] are only those function calls in which the postfix-expression ultimately contains an id-expression that denotes one or more functions. Such a postfix-expression, perhaps nested arbitrarily deep in parentheses, has one of the following forms: postfix-expression:postfix-expression. id-expressionpostfix-expression -> id-expressionprimary-expression These represent two syntactic subcategories of function calls: qualified function calls and unqualified function calls.

In qualified function calls, the function is named by an id-expression preceded by an -> or. operator. Since the construct A->B is generally equivalent to (*A).B, the rest of [over] assumes, without loss of generality, that all member function calls have been normalized to the form that uses an object and the. operator. Furthermore, [over] assumes that the postfix-expression that is the left operand of the. operator has type “cv T” where T denotes a class. The function declarations found by name lookup ([class.member.lookup]) constitute the set of candidate functions. The argument list is the expression-list in the call augmented by the addition of the left operand of the. operator in the normalized member function call as the implied object argument ([over.match.funcs]).

In unqualified function calls, the function is named by a primary-expression. The function declarations found by name lookup ([basic.lookup]) constitute the set of candidate functions. Because of the rules for name lookup, the set of candidate functions consists either entirely of non-member functions or entirely of member functions of some class T. In the former case or if the primary-expression is the address of an overload set, the argument list is the same as the expression-list in the call. Otherwise, the argument list is the expression-list in the call augmented by the addition of an implied object argument as in a qualified function call. If the current class is, or is derived from, T, and the keyword this ([expr.prim.this]) refers to it, then the implied object argument is (*this). Otherwise, a contrived object of type T becomes the implied object argument; if overload resolution selects a non-static member function, the call is ill-formed. [Example 1:

struct C {
 void a();
 void b() {
 a(); // OK, (*this).a()
 }
void c(this const C&); // #1
void c()&; // #2
static void c(int = 0); // #3
void d() {
 c(); // error: ambiguous between #2 and #3
 (C::c)(); // error: as above
 (&(C::c))(); // error: cannot resolve address of overloaded this->C​::​c ([over.over])
 (&C::c)(C{}); // selects #1
 (&C::c)(*this); // error: selects #2, and is ill-formed ([over.match.call.general])
 (&C::c)(); // selects #3
}
 void f(this const C&);
 void g() const {
 f(); // OK, (*this).f()
 f(*this); // error: no viable candidate for (*this).f(*this)
 this->f(); // OK
 }
 static void h() {
 f(); // error: contrived object argument, but overload resolution
 // picked a non-static member function
 f(C{}); // error: no viable candidate
 C{}.f(); // OK
 }
 void k(this int);
 operator int() const;
 void m(this const C& c) {
 c.k(); // OK
 }
};

— end example]

If the postfix-expression E in the function call syntax evaluates to a class object of type “cv T”, then the set of candidate functions includes at least the function call operators of T. The function call operators of T are the results of a search for the name operator() in the scope of T.

In addition, for each non-explicit conversion function declared in T of the form operator conversion-type-id () cv-qualifier-seqopt ref-qualifieropt noexcept-specifieropt attribute-specifier-seqopt; where the optional cv-qualifier-seq is the same cv-qualification as, or a greater cv-qualification than, cv, and where conversion-type-id denotes the type “pointer to function of (P1,…,Pn) returning R”, or the type “reference to pointer to function of (P1,…,Pn) returning R”, or the type “reference to function of (P1,…,Pn) returning R”, a surrogate call function with the unique name call-function and having the form R call-function (conversion-type-id F, P1 a1, …, Pn an) { return F (a1, …, an); } is also considered as a candidate function. Similarly, surrogate call functions are added to the set of candidate functions for each non-explicit conversion function declared in a base class of T provided the function is not hidden within T by another intervening declaration.

The argument list submitted to overload resolution consists of the argument expressions present in the function call syntax preceded by the implied object argument (E). [Note 1: When comparing the call against the function call operators, the implied object argument is compared against the object parameter of the function call operator. When comparing the call against a surrogate call function, the implied object argument is compared against the first parameter of the surrogate call function. — end note] [Example 1:

int f1(int);
int f2(float);
typedef int (*fp1)(int);
typedef int (*fp2)(float);
struct A {
 operator fp1() { return f1; }
 operator fp2() { return f2; }
} a;
int i = a(1); // calls f1 via pointer returned from conversion function

— end example]

When resolving a placeholder for a deduced class type ([dcl.type.class.deduct]) where the template-name names a primary class template C, a set of functions and function templates, called the guides of C, is formed comprising: If C is defined, for each constructor of C, a function template with the following properties: The template parameters are the template parameters of C followed by the template parameters (including default template arguments) of the constructor, if any.The types of the function parameters are those of the constructor.The return type is the class template specialization designated by C and template arguments corresponding to the template parameters of C.If C is not defined or does not declare any constructors, an additional function template derived as above from a hypothetical constructor C().An additional function template derived as above from a hypothetical constructor C(C), called the copy deduction candidate.For each deduction-guide, a function or function template with the following properties: The template parameters, if any, and function parameters are those of the deduction-guide.The return type is the simple-template-id of the deduction-guide. In addition, if C is defined and its definition satisfies the conditions for an aggregate class ([dcl.init.aggr]) with the assumption that any dependent base class has no virtual functions and no virtual base classes, and the initializer is a non-empty braced-init-list or parenthesized expression-list, and there are no deduction-guides for C, the set contains an additional function template, called the aggregate deduction candidate, defined as follows. Let x1,…,xn be the elements of the initializer-list or designated-initializer-list of the braced-init-list, or of the expression-list. For each xi, let ei be the corresponding aggregate element of C or of one of its (possibly recursive) subaggregates that would be initialized by xi ([dcl.init.aggr]) if brace elision is not considered for any aggregate element that has a dependent non-array type,an array type with a value-dependent bound, oran array type with a dependent array element type and xi is a string literal; andeach non-trailing aggregate element that is a pack expansion is assumed to correspond to no elements of the initializer list, anda trailing aggregate element that is a pack expansion is assumed to correspond to all remaining elements of the initializer list (if any). If there is no such aggregate element ei for any xi, the aggregate deduction candidate is not added to the set. The aggregate deduction candidate is derived as above from a hypothetical constructor C(T1,…,Tn), where if ei is of array type and xi is a braced-init-list, Ti is an rvalue reference to the declared type of ei, andif ei is of array type and xi is a string-literal, Ti is an lvalue reference to the const-qualified declared type of ei, andotherwise, Ti is the declared type of ei, except that additional parameter packs of the form Pj... are inserted into the parameter list in their original aggregate element position corresponding to each non-trailing aggregate element of type Pj that was skipped because it was a parameter pack, and the trailing sequence of parameters corresponding to a trailing aggregate element that is a pack expansion (if any) is replaced by a single parameter of the form Tn.... In addition, if C is defined and inherits constructors ([namespace.udecl]) from a direct base class denoted in the base-specifier-list by a class-or-decltype B, let A be an alias template whose template parameter list is that of C and whose defining-type-id is B. If A is a deducible template ([dcl.type.simple]), the set contains the guides of A with the return type R of each guide replaced with typename CC<R>:: type given a class template

template <typename> class CC;

whose primary template is not defined and with a single partial specialization whose template parameter list is that of A and whose template argument list is a specialization of A with the template argument list of A ([temp.dep.type]) having a member typedef type designating a template specialization with the template argument list of A but with C as the template. [Note 1: Equivalently, the template parameter list of the specialization is that of C, the template argument list of the specialization is B, and the member typedef names C with the template argument list of C. — end note]

[Example 1:

template <typename T> struct B {
 B(T);
};
template <typename T> struct C : public B<T> {
 using B<T>::B;
};
template <typename T> struct D : public B<T> {};
C c(42); // OK, deduces C<int>
D d(42); // error: deduction failed, no inherited deduction guides
B(int) -> B<char>;
C c2(42); // OK, deduces C<char>
template <typename T> struct E : public B<int> {
 using B<int>::B;
};
E e(42); // error: deduction failed, arguments of E cannot be deduced from introduced guides
template <typename T, typename U, typename V> struct F {
 F(T, U, V);
};
template <typename T, typename U> struct G : F<U, T, int> {
 using G::F::F;
}
G g(true, 'a', 1); // OK, deduces G<char, bool>
template<class T, std::size_t N>
struct H {
 T array[N];
};
template<class T, std::size_t N>
struct I {
 volatile T array[N];
};
template<std::size_t N>
struct J {
 unsigned char array[N];
};
H h = { "abc" }; // OK, deduces H<char, 4> (not T = const char)
I i = { "def" }; // OK, deduces I<char, 4>
J j = { "ghi" }; // error: cannot bind reference to array of unsigned char to array of char in deduction

— end example]

The arguments of a template A are said to be deducible from a type T if, given a class template

template <typename> class AA;

with a single partial specialization whose template parameter list is that of A and whose template argument list is a specialization of A with the template argument list of A ([temp.dep.type]), AA<T> matches the partial specialization.

[Example 2:

