module;
#include "X.h"
export module M2;
import M1;
void h(Q::X x) {
 g(x); // OK
}

— end example]

[Example 2: Module interface unit of Std:

export module Std;
export template<typename Iter>
void indirect_swap(Iter lhs, Iter rhs)
{
 swap(*lhs, *rhs); // swap not found by unqualified lookup, can be found only via ADL
}

