{
 indirect_swap(p, q); // finds #1 via ADL in instantiation context
}

— end example]

[Example 3: Source file "X.h":

struct X { /* ... */ };
X operator+(X, X);

Module interface unit of F:

export module F;
export template<typename T>
void f(T t) {
 t + t;
}

