 f(x); // OK, instantiates f from F,
 // operator+ is visible in instantiation context
}

— end example]

[Example 4: Module interface unit of A:

export module A;
export template<typename T>
void f(T t) {
 cat(t, t); // #1
 dog(t, t); // #2
}

